if not L then return end

-- Human translators the About page credits (display names only; the AI is named in the header above).
L[0] = {}

addon.translation = {
-- d6f5cde1 English: Observe memory for ten minutes without changing polling or forcing garbage
--     collection. /rm perf memory accepts 1–1800 seconds (default 600), plus stop and report.
--     Whole-Lua heap is sampled each second; bounded retained counts every thirty seconds. Addon
--     attribution refreshes only at start and completion; intermediate values are cached with
--     unknown age. Stop completes the final boundary before you open the report. Refreshes can
--     hitch, and their cost is reported. Heap decreases do not prove collection or a leak.
[3042] = "Den Speicher zehn Minuten lang beobachten, ohne das Polling zu ändern oder die Speicherbereinigung zu erzwingen. /rm perf memory akzeptiert 1–1800 Sekunden (Standard 600) sowie stop und report. Der gesamte Lua-Heap wird jede Sekunde abgetastet; begrenzt gehaltene Zähler alle dreißig Sekunden. Die Zuordnung zu Addons wird nur bei Start und Abschluss aktualisiert; Zwischenwerte werden mit unbekanntem Alter zwischengespeichert. Stop schließt die letzte Grenze ab, bevor Sie den Bericht öffnen. Aktualisierungen können kurze Ruckler verursachen, und ihre Kosten werden gemeldet. Ein sinkender Heap beweist weder eine Bereinigung noch ein Leck.",
-- 65848052 English: Open the copyable lifetime report: whole-heap range and decreases, start/end
--     addon attribution, explicitly cached intermediate values, retained key/row counts and capture
--     overhead. Counts are not bytes; unavailable and capped observations stay explicit. Viewing
--     the report never resamples memory.
[3043] = "Den kopierbaren Lebenszeitbericht öffnen: Bereich und Rückgänge des gesamten Heaps, Addon-Zuordnung bei Start und Ende, ausdrücklich zwischengespeicherte Zwischenwerte, Zähler gehaltener Schlüssel und Zeilen sowie der Aufwand der Erfassung. Zähler sind keine Bytes; nicht verfügbare und gedeckelte Beobachtungen bleiben ausdrücklich gekennzeichnet. Das Anzeigen des Berichts tastet den Speicher nie erneut ab.",
-- 35fde7b4 English: Measure normal rotation evaluation calls for ten seconds with the native
--     profiler. /rm perf runtime accepts 1–60 seconds (default 10), plus stop and report. The
--     512-dispatch safety limit can end a longer capture sooner. Polling stays unchanged. Stop
--     finalizes partial measurements; the legacy Cancel capture action still cancels. Close
--     configuration after starting. Instrumentation adds overhead; allocation is not retained
--     memory or proof of a leak. Cumulative CPU captures cannot overlap this capture.
[3044] = "Misst zehn Sekunden lang die normalen Aufrufe der Rotationsauswertung mit dem nativen Profiler. /rm perf runtime akzeptiert 1–60 Sekunden (Standard 10) sowie stop und report. Das Sicherheitslimit von 512 Aufrufen kann eine längere Erfassung früher beenden. Die Abfrage bleibt unverändert. Stop schließt Teilmessungen ab; die alte Aktion „Erfassung abbrechen“ bricht weiterhin ab. Nach dem Start die Konfiguration schließen. Die Instrumentierung verursacht zusätzlichen Aufwand; Allokationen sind weder belegter Speicher noch ein Beweis für ein Leck. Kumulative CPU-Erfassungen können nicht gleichzeitig mit dieser Erfassung laufen.",
-- b429fad0 English: Open the copyable runtime report: measured evaluation calls, native elapsed
--     time and gross allocation/deallocation counters. Missing metrics remain unavailable.
--     Measurement covers evaluation calls only, not all addon events or rendering. Reading the
--     report does not sample gameplay.
[3045] = "Öffnet den kopierbaren Laufzeitbericht: gemessene Auswertungsaufrufe, native verstrichene Zeit sowie Brutto-Zähler für Allokation und Freigabe. Fehlende Messwerte bleiben nicht verfügbar. Gemessen werden nur Auswertungsaufrufe, nicht alle Addon-Ereignisse oder das Rendern. Das Lesen des Berichts erfasst keine Spieldaten.",
-- 0eebb1cd English: Enable observation cache
-- Context: Help topic title (General settings help) for the option in the performance section that
--     turns the observation cache on or off.
[3046] = "Beobachtungscache aktivieren",
-- 5309abf9 English: Optional reuse of repeated getCached and getRetryCached lookups. Observation
--     caching is off by default to reduce table allocations; enabling it can help conditions that
--     repeat the same lookup. Compiled condition facts are independent of this option. The checkbox
--     shows the saved choice for the next reload. Pending means it differs from the running mode.
--     Use /reload to apply it; no full game restart is needed. This choice saves immediately
--     without applying or discarding other pending settings.
[3047] = "Optionale Wiederverwendung wiederholter getCached- und getRetryCached-Abfragen. Der Beobachtungscache ist standardmäßig aus, um Tabellenallokationen zu verringern; das Aktivieren kann Bedingungen helfen, die dieselbe Abfrage wiederholen. Kompilierte Bedingungsfakten sind von dieser Option unabhängig. Das Kontrollkästchen zeigt die gespeicherte Wahl für das nächste Neuladen. „Ausstehend“ bedeutet, dass sie vom laufenden Modus abweicht. Mit /reload wird sie angewendet; ein Neustart des Spiels ist nicht nötig. Diese Wahl wird sofort gespeichert, ohne andere ausstehende Einstellungen anzuwenden oder zu verwerfen.",
-- e2747e8f English: Capture native cumulative function CPU costs and call counts for ten seconds.
--     /rm perf cpu starts the same capture; /rm perf cpu 30 chooses 30 seconds (range 1–60). /rm
--     perf cpu stop finalizes partial counters; /rm perf cpu report opens the copyable result.
--     Capture uses live settings and does not apply pending changes. Close configuration after
--     starting. WoW scriptProfile must already be enabled before a reload; RM never changes it or
--     resets shared counters. Profiling itself adds overhead.
[3048] = "Erfasst zehn Sekunden lang die nativen kumulativen CPU-Kosten und Aufrufzahlen von Funktionen. /rm perf cpu startet dieselbe Erfassung; /rm perf cpu 30 wählt 30 Sekunden (Bereich 1–60). /rm perf cpu stop schließt Teilzähler ab; /rm perf cpu report öffnet das kopierbare Ergebnis. Die Erfassung verwendet die aktiven Einstellungen und wendet keine ausstehenden Änderungen an. Nach dem Start die Konfiguration schließen. WoW-scriptProfile muss bereits vor einem Neuladen aktiviert sein; RM ändert es nie und setzt keine gemeinsamen Zähler zurück. Das Profiling selbst verursacht zusätzlichen Aufwand.",
-- 144f6416 English: Open a selectable, copyable report with total addon CPU, measured function
--     costs and calls, sample boundaries, and unavailable or replaced functions. Inclusive costs
--     overlap and must not be added together. Boundary state does not prove configuration or combat
--     stayed unchanged throughout the capture. Untracked functions and native work may account for
--     remaining costs.
[3049] = "Öffnet einen markier- und kopierbaren Bericht mit der gesamten Addon-CPU, den gemessenen Kosten und Aufrufen der Funktionen, den Stichprobengrenzen sowie nicht verfügbaren oder ersetzten Funktionen. Inklusive Kosten überschneiden sich und dürfen nicht addiert werden. Der Zustand an den Grenzen beweist nicht, dass Konfiguration oder Kampf während der gesamten Erfassung unverändert blieben. Nicht erfasste Funktionen und native Arbeit können die verbleibenden Kosten erklären.",
-- 8c53a218 English: Choose a source helper and its name in this Lua body, such as custom.ready or
--     utils.getCached. These are dependency records even when the source and local names match; a
--     different local name is an optional alias. The records identify helpers for loading, export
--     and availability checks. Accepting a completion records the dependency automatically. Typing
--     a call does not infer a dependency: add its qualified name explicitly or accept a completion.
--     WoW globals and existing addon APIs remain directly available. Namespaces are private to this
--     callback and do not supply self. Pass a method receiver explicitly in a namespaced dot call;
--     object:method(x) is shorthand for object.method(object, x). Click the bound source name to
--     open its function; the adjacent arrow changes the mapping. Pending edits offer Apply, Discard
--     or Cancel before navigation. Renaming a function, namespace or binding does not rewrite code.
--     Missing, disabled or invalid dependencies keep consumers unavailable.
[3050] = "Wählen Sie einen Quellhelfer und seinen Namen in diesem Lua-Rumpf, etwa custom.ready oder utils.getCached. Dies sind Abhängigkeitseinträge, auch wenn Quell- und lokaler Name übereinstimmen; ein abweichender lokaler Name ist ein optionaler Alias. Die Einträge kennzeichnen Helfer für das Laden, den Export und Verfügbarkeitsprüfungen. Das Übernehmen einer Vervollständigung erfasst die Abhängigkeit automatisch. Das Eintippen eines Aufrufs leitet keine Abhängigkeit ab: Den qualifizierten Namen ausdrücklich hinzufügen oder eine Vervollständigung übernehmen. WoW-Globale und vorhandene Addon-APIs bleiben direkt verfügbar. Namensräume sind privat für diesen Callback und liefern kein self. Bei einem Punktaufruf über einen Namensraum den Methodenempfänger ausdrücklich übergeben; object:method(x) ist die Kurzform für object.method(object, x). Ein Klick auf den gebundenen Quellnamen öffnet dessen Funktion; der Pfeil daneben ändert die Zuordnung. Bei ausstehenden Bearbeitungen werden vor dem Wechsel Übernehmen, Verwerfen oder Abbrechen angeboten. Das Umbenennen einer Funktion, eines Namensraums oder einer Bindung schreibt keinen Code um. Fehlende, deaktivierte oder ungültige Abhängigkeiten halten ihre Verwender nicht verfügbar.",
-- 476ed166 English: Validity Function
-- Context: Yellow heading in the custom condition help: the function that checks the condition
--     itself is valid (all required fields have valid values).
[3051] = "Gültigkeitsfunktion",
-- fb4e0028 English: Evaluation Function
-- Context: Yellow heading in the custom condition help: the function that evaluates the condition
--     at run time and returns true or false.
[3052] = "Auswertungsfunktion",
-- d7868586 English: Print Function
-- Context: Yellow heading in the custom condition help: the function that produces the condition's
--     one-line summary text.
[3053] = "Ausgabefunktion",
-- d548d39d English: Widget Function
-- Context: Yellow heading in the custom condition help: the function that builds the condition's
--     editing widgets.
[3054] = "Widget-Funktion",
-- e136f1bc English: Help Function
-- Context: Yellow heading in the custom condition help: the function that builds the condition's
--     own help page.
[3055] = "Hilfefunktion",
-- 4efca0d1 English: About
-- Context: Name of the About page of the settings window (version, author, credits and links); also
--     the title of its help window.
[3056] = "Über",
-- 96c34a07 English: Invalid
-- Context: Status label (with icon) in the rotation help: the rotation or step is not valid, so it
--     cannot be used.
[3057] = "Ungültig",
-- 29ab8f0c English: Currently satisfied
-- Context: Status label (with icon) in the rotation help and on rotation cards: the conditions are
--     true right now (shown green).
[3058] = "Derzeit erfüllt",
-- 28f0d12b English: Not currently satisfied
-- Context: Status label (with icon) in the rotation help and on rotation cards: the conditions are
--     not true right now (shown red).
[3059] = "Derzeit nicht erfüllt",
-- 82e28aca English: True while your enabled boss mod (DBM or BigWigs, chosen on the Integrations
--     page) reports a boss encounter in progress. Leave Encounter ID blank for any encounter, or
--     enter the game's encounter ID, which DBM and BigWigs share, to match one boss; while an
--     encounter is active the editor shows its name and ID. This is the boss mod's report, not game
--     state: it starts when the boss mod engages and ends when it records a win, wipe or reset. Use
--     it as a switch condition for encounter-specific rotations; automatic switching picks it up on
--     its normal re-check interval. Unavailable, never simply false, when no boss mod is enabled or
--     loaded.
[3060] = "Wahr, solange Ihr aktivierter Boss-Mod (DBM oder BigWigs, gewählt auf der Seite Integrationen) eine laufende Bossbegegnung meldet. Die Begegnungs-ID leer lassen, um jede Begegnung zu erfassen, oder die Begegnungs-ID des Spiels eingeben, die DBM und BigWigs gemeinsam verwenden, um einen bestimmten Boss zu erfassen; während eine Begegnung läuft, zeigt der Editor ihren Namen und ihre ID. Dies ist die Meldung des Boss-Mods, nicht der Spielzustand: Sie beginnt, wenn der Boss-Mod den Kampf erkennt, und endet, wenn er einen Sieg, einen Wipe oder ein Zurücksetzen verzeichnet. Als Umschaltbedingung für begegnungsspezifische Rotationen verwenden; der automatische Wechsel erkennt sie im normalen Intervall der erneuten Prüfung. Nicht verfügbar, niemals einfach falsch, wenn kein Boss-Mod aktiviert oder geladen ist.",
-- 67327949 English: The stage (phase) your boss mod reports for the current encounter. An encounter
--     whose boss mod has not reported a stage counts as stage 1, and some intermissions are
--     reported as half stages such as 1.5. False when no encounter is in progress; unavailable when
--     no boss mod is enabled or loaded.
[3061] = "Die Phase, die Ihr Boss-Mod für die aktuelle Begegnung meldet. Eine Begegnung, für die der Boss-Mod noch keine Phase gemeldet hat, gilt als Phase 1, und manche Zwischenphasen werden als halbe Phasen gemeldet, etwa 1.5. Falsch, wenn keine Begegnung läuft; nicht verfügbar, wenn kein Boss-Mod aktiviert oder geladen ist.",
-- 0aea56a9 English: Compares the time left on your boss mod's timer for one boss ability,
--     identified by the ability's spell ID; while timers run, the editor lists them with their IDs.
--     Timers are the boss mod's predictions and can shift, pause or be canceled. When no timer for
--     that ability is running the condition is false, so 'is less than 5 seconds' is only true
--     while a timer is actually counting down. Bars without a spell ID, such as pull or respawn
--     timers, are not tracked. Unavailable when no boss mod is enabled or loaded.
[3062] = "Vergleicht die verbleibende Zeit des Boss-Mod-Timers für eine Bossfähigkeit, die über ihre Zauber-ID bestimmt wird; während Timer laufen, listet der Editor sie mit ihren IDs auf. Timer sind Vorhersagen des Boss-Mods und können sich verschieben, pausieren oder abgebrochen werden. Läuft für diese Fähigkeit kein Timer, ist die Bedingung falsch, sodass „ist kleiner als 5 Sekunden“ nur wahr ist, solange tatsächlich ein Timer herunterzählt. Leisten ohne Zauber-ID, etwa Pull- oder Respawn-Timer, werden nicht verfolgt. Nicht verfügbar, wenn kein Boss-Mod aktiviert oder geladen ist.",
-- 68c38a65 English: Sound Alert
-- Context: Yellow heading in the rotation help, in the announcements part: the sound that can be
--     played along with an announcement.
[3063] = "Akustischer Alarm",
-- 7a0ac7f9 English: Any (OR) checks children in order and stops at the first match. An empty group
--     does not match. Encountered unavailable data remains unavailable; later children are skipped.
[3064] = "Beliebig (OR) prüft die Unterbedingungen der Reihe nach und hält beim ersten Treffer an. Eine leere Gruppe trifft nicht zu. Angetroffene nicht verfügbare Daten bleiben nicht verfügbar; spätere Unterbedingungen werden übersprungen.",
-- 0cda3eb2 English: Every rotation has an identifier (ID), shown beside its priority: type /rm set
--     <id> to choose it (any case), /rm set auto to go back to automatic switching, and /rm list to
--     see every identifier. A Built In's identifier is fixed; yours is made from its name until you
--     change it.
[3065] = "Jede Rotation hat einen Bezeichner (ID), der neben ihrer Priorität steht: Geben Sie /rm set <id> ein, um sie zu wählen (Groß- und Kleinschreibung egal), /rm set auto, um zum automatischen Wechsel zurückzukehren, und /rm list, um alle Bezeichner anzuzeigen. Der Bezeichner einer integrierten Rotation ist fest; Ihrer wird aus dem Namen gebildet, bis Sie ihn ändern.",
-- 5530025a English: Choosing a rotation
-- Context: Heading in the rotation help: how the addon decides which rotation is used. Noun phrase
--     with gerund.
[3066] = "Eine Rotation wählen",
-- 359bbdff English: Automatic switching tries the enabled rotations in priority order, yours and
--     Built Ins alike: higher numbers are tried first, equal priorities by name. It picks the first
--     that matches; a rotation with no switch condition always matches, so turn it off to keep it
--     from being chosen. The fallback (Default) is used only when none matches. The rotation list
--     is sorted in this same order and shows each priority.
[3067] = "Der automatische Wechsel probiert die aktivierten Rotationen in der Reihenfolge ihrer Priorität durch, eigene und integrierte gleichermaßen: Höhere Zahlen kommen zuerst, bei gleicher Priorität entscheidet der Name. Er wählt die erste, die passt; eine Rotation ohne Umschaltbedingung passt immer, also schalten Sie sie ab, damit sie nicht gewählt wird. Die Ersatzrotation (Standard) wird nur verwendet, wenn keine passt. Die Rotationsliste ist in derselben Reihenfolge sortiert und zeigt jede Priorität.",
-- 1adf9c9d English: Priority sits beside Enabled at the top of the editor. A Built In cannot be
--     edited, but its Enabled setting and priority are yours to change for this profile: they are
--     saved at once, shown in amber when they differ from how it ships, and Reset to default puts
--     it back. Copy a Built In to your rotations to edit anything else.
[3068] = "Die Priorität steht im Editor oben neben Aktiviert. Eine integrierte Rotation kann nicht bearbeitet werden, aber ihre Einstellung Aktiviert und ihre Priorität können Sie für dieses Profil ändern: Beides wird sofort gespeichert, bernsteinfarben angezeigt, wenn es von der Auslieferung abweicht, und Auf Standard zurücksetzen stellt es wieder her. Kopieren Sie eine integrierte Rotation in Ihre Rotationen, um alles andere zu bearbeiten.",
-- 89d48b07 English: A Built In shows a blue Read-Only pill in place of Undo and Redo; Duplicate
--     makes your own copy. It loads only for the edition and class it was written for (the pill's
--     tooltip). The specializations it is for show in the picker before its name; any level it
--     needs is part of its switch condition. The switch's tooltip says when it can be selected
--     together with another rotation, or is for another specialization.
[3069] = "Eine integrierte Rotation zeigt anstelle von Rückgängig und Wiederherstellen eine blaue Schreibgeschützt-Plakette; Duplizieren erstellt Ihre eigene Kopie. Sie wird nur für die Edition und die Klasse geladen, für die sie geschrieben wurde (der Tooltip der Plakette). Die Spezialisierungen, für die sie gilt, stehen in der Auswahl vor ihrem Namen; eine erforderliche Stufe ist Teil ihrer Umschaltbedingung. Der Tooltip des Schalters sagt, wann sie zusammen mit einer anderen Rotation gewählt werden kann oder für eine andere Spezialisierung gilt.",
-- c85105a0 English: In the list, a red border means the rotation cannot be selected (the tooltip
--     names why), gray means it is switched off, and an amber bar means it can be selected at the
--     same time as another rotation (yours or Built In), so only priority decides between them; a
--     wider bar means they also have the same priority and the name decides. /rm why lists the
--     order and what automatic switching would choose now.
[3070] = "In der Liste bedeutet ein roter Rand, dass die Rotation nicht gewählt werden kann (der Tooltip nennt den Grund), Grau bedeutet, dass sie abgeschaltet ist, und ein bernsteinfarbener Balken bedeutet, dass sie gleichzeitig mit einer anderen Rotation (eigene oder integrierte) gewählt werden kann, sodass nur die Priorität zwischen beiden entscheidet; ein breiterer Balken bedeutet, dass sie auch dieselbe Priorität haben und der Name entscheidet. /rm why listet die Reihenfolge auf und zeigt, was der automatische Wechsel jetzt wählen würde.",
-- 929902f7 English: Each rotation says which specializations it is for, in the picker before its
--     name: several, or Any. It is listed, in the minimap menu and for /rm set, only while you play
--     one of them; its switch condition never hides it. Automatic switching checks the
--     specialization first, then the switch condition, then priority; a rotation with no switch
--     condition matches whenever its specialization and level apply, so priority alone decides;
--     turn it off to keep it for choosing by hand. The specialization menu above the list's search
--     box starts at the one you are playing; choose another, or All specializations, to see theirs.
--     Where the game has dual specialization instead of named specializations (Classic Era, TBC,
--     Wrath, Cataclysm and Forever), they are your primary and secondary talents: exports leave
--     them out, and an import is for the talents the list shows.
[3071] = "Jede Rotation gibt in der Auswahl vor ihrem Namen an, für welche Spezialisierungen sie gilt: mehrere oder Beliebig. Sie wird im Minikartenmenü und für /rm set nur aufgelistet, solange Sie eine davon spielen; ihre Umschaltbedingung blendet sie nie aus. Der automatische Wechsel prüft zuerst die Spezialisierung, dann die Umschaltbedingung, dann die Priorität; eine Rotation ohne Umschaltbedingung passt, sobald ihre Spezialisierung und Stufe zutreffen, sodass allein die Priorität entscheidet; schalten Sie sie ab, um sie nur von Hand zu wählen. Das Spezialisierungsmenü über dem Suchfeld der Liste beginnt bei der Spezialisierung, die Sie gerade spielen; wählen Sie eine andere oder Alle Spezialisierungen, um deren Rotationen zu sehen. Wo das Spiel statt benannter Spezialisierungen eine Doppelspezialisierung hat (Classic Era, TBC, Wrath, Cataclysm und Forever), sind das Ihre primären und sekundären Talente: Exporte lassen sie weg, und ein Import gilt für die Talente, die die Liste zeigt.",
-- 4c969557 English: Stop ends lower priority actions. The implicit auto-attack (Attack or Shoot)
--     remains eligible unless you suppress it. An unavailable Stop condition also suppresses it.
--     Optional reminders remain independent.
[3072] = "Stopp beendet Aktionen mit niedrigerer Priorität. Der implizite automatische Angriff (Angriff oder Schießen) bleibt zulässig, sofern er nicht unterdrückt wird. Eine nicht verfügbare Stopp-Bedingung unterdrückt ihn ebenfalls. Optionale Erinnerungen bleiben unabhängig.",
-- 4db9065c English: All (AND) checks children in order and stops at the first non-match. An empty
--     group matches. Encountered unavailable data remains unavailable; later children are skipped.
[3073] = "Alle (AND) prüft die Unterbedingungen der Reihe nach und hält bei der ersten Nichtübereinstimmung an. Eine leere Gruppe trifft zu. Angetroffene nicht verfügbare Daten bleiben nicht verfügbar; spätere Unterbedingungen werden übersprungen.",
-- 2253ae22 English: Select cards with Ctrl-click or Shift-click. Group with All or Any, negate
--     each, move or drag, and remove. Undo and Redo affect only the draft until Apply. Groups can
--     be named and collapsed.
[3074] = "Karten mit Strg-Klick oder Umschalt-Klick auswählen. Mit Alle oder Beliebig gruppieren, jede negieren, verschieben oder ziehen und entfernen. Rückgängig und Wiederherstellen wirken bis zum Übernehmen nur auf den Entwurf. Gruppen können benannt und eingeklappt werden.",
-- ef5cde35 English: Built In and custom rotations use the same cards. Built In rotations are
--     read-only; enable or disable them, inspect their conditions, or Duplicate to edit.
[3075] = "Integrierte und benutzerdefinierte Rotationen verwenden dieselben Karten. Integrierte Rotationen sind schreibgeschützt; sie können aktiviert oder deaktiviert, ihre Bedingungen angesehen oder sie zum Bearbeiten dupliziert werden.",
-- 598c73a5 English: Custom edits stay in a private draft. Apply saves; Discard restores the saved
--     rotation. Undo and Redo include card deletion, movement, fields and conditions. Apply before
--     reloading or logging out.
[3076] = "Benutzerdefinierte Bearbeitungen bleiben in einem privaten Entwurf. Übernehmen speichert; Verwerfen stellt die gespeicherte Rotation wieder her. Rückgängig und Wiederherstellen umfassen das Löschen und Verschieben von Karten, Felder und Bedingungen. Vor dem Neuladen oder Abmelden übernehmen.",
-- 55e4c200 English: Closing the window retains drafts for this session. Switching rotations or
--     opening comparison or transfer asks whether to Apply, Discard or Cancel when changes are
--     pending.
[3077] = "Beim Schließen des Fensters bleiben Entwürfe für diese Sitzung erhalten. Beim Wechseln der Rotation oder beim Öffnen von Vergleich oder Übertragung wird bei ausstehenden Änderungen gefragt, ob übernommen, verworfen oder abgebrochen werden soll.",
-- 770e0bb6 English: The switch condition selects the rotation automatically; with none, it is
--     selected whenever its specialization and level apply. Edit changes its condition tree. The
--     fallback rotation is selected when no other rotation matches.
[3078] = "Die Umschaltbedingung wählt die Rotation automatisch; ohne Umschaltbedingung wird sie gewählt, sobald ihre Spezialisierung und Stufe zutreffen. Bearbeiten ändert ihren Bedingungsbaum. Die Ersatzrotation wird gewählt, wenn keine andere Rotation passt.",
-- 7423362f English: Cooldown cards have their own scrolling workspace and highlight independently
--     of the sequence. Add cooldown creates a reminder; clicking its action shows local highlight
--     settings.
[3079] = "Abklingzeitkarten haben einen eigenen scrollbaren Arbeitsbereich und werden unabhängig von der Sequenz hervorgehoben. „Abklingzeit hinzufügen“ erstellt eine Erinnerung; ein Klick auf ihre Aktion zeigt die lokalen Hervorhebungseinstellungen.",
-- 758bf6a1 English: Add action appends a priority action. Drag an Add control into a gap to insert
--     there. Click a card name to rename it, expand for action fields, or click its condition text
--     to edit the guard.
[3080] = "„Aktion hinzufügen“ hängt eine Prioritätsaktion an. Ein Hinzufügen-Element in eine Lücke ziehen, um dort einzufügen. Auf einen Kartennamen klicken, um ihn umzubenennen, die Karte für Aktionsfelder aufklappen oder auf ihren Bedingungstext klicken, um die Vorbedingung zu bearbeiten.",
-- 9b6cac99 English: Adding a branch moves following steps into its True arm. False is on the left
--     in red; True is on the right in green. The mode pill cycles Evaluate condition, Always true
--     and Always false. Unreachable cards are gray.
[3081] = "Beim Hinzufügen einer Verzweigung wandern die folgenden Schritte in ihren Wahr-Zweig. Falsch ist links in Rot; Wahr ist rechts in Grün. Die Modusschaltfläche wechselt zwischen Bedingung auswerten, Immer wahr und Immer falsch. Nicht erreichbare Karten sind grau.",
-- 5fc9817f English: Ordinary dragging moves one card and its own subtree. Hold Ctrl when starting a
--     drag to carry that card and every following sibling, including their branch subtrees. Drop
--     into a branch arm gap to move there. Up / Down always moves one card. A group cannot be
--     dropped into itself or a carried descendant.
[3082] = "Normales Ziehen verschiebt eine Karte samt ihrem eigenen Unterbaum. Wird beim Beginn des Ziehens Strg gehalten, werden diese Karte und alle folgenden Geschwister einschließlich ihrer Verzweigungsunterbäume mitgenommen. Zum Verschieben in eine Lücke eines Verzweigungszweigs ziehen. Hoch / Runter verschiebt immer eine Karte. Eine Gruppe kann nicht in sich selbst oder einen mitgenommenen Nachfahren gezogen werden.",
-- a6e094f9 English: An evaluated branch follows one arm, then rejoins later siblings. Stop ends the
--     sequence. Independent cooldowns still apply; implicit auto-attack (Attack or Shoot) remains
--     available unless the Stop suppresses it.
[3083] = "Eine ausgewertete Verzweigung folgt einem Zweig und führt danach wieder zu späteren Geschwistern zurück. Stopp beendet die Sequenz. Unabhängige Abklingzeiten gelten weiterhin; der implizite automatische Angriff (Angriff oder Schießen) bleibt verfügbar, sofern der Stopp ihn nicht unterdrückt.",
-- 4e0f26c5 English: Invalid or incomplete cards remain editable. Apply validates both branch arms
--     without running custom condition code. Deleting a whole custom rotation requires confirmation
--     and cannot be undone.
[3084] = "Ungültige oder unvollständige Karten bleiben bearbeitbar. Übernehmen validiert beide Verzweigungszweige, ohne Code benutzerdefinierter Bedingungen auszuführen. Das Löschen einer ganzen benutzerdefinierten Rotation erfordert eine Bestätigung und kann nicht rückgängig gemacht werden.",
-- c54e950a English: List and Cooldowns use flat scrollbars or the mouse wheel. Diagram uses wheel
--     zoom and dragging empty space to pan. Window scaling applies when the slider is released and
--     also affects RM child windows.
[3085] = "Liste und Abklingzeiten verwenden flache Bildlaufleisten oder das Mausrad. Das Diagramm zoomt mit dem Mausrad und lässt sich durch Ziehen auf leerer Fläche verschieben. Die Fensterskalierung wird beim Loslassen des Schiebereglers angewendet und wirkt sich auch auf untergeordnete RM-Fenster aus.",
-- e90e0aef English: Highlight preview
-- Context: Help topic title in General settings help for the highlight preview (the example that
--     shows the chosen highlight).
[3086] = "Hervorhebungsvorschau",
-- aafdf428 English: Add category
-- Context: Help topic title in the Conditions help for the Add category button.
[3087] = "Kategorie hinzufügen",
-- 539a15c9 English: Choose and edit
-- Context: Section title in the condition editor help: how to choose a condition type and edit its
--     fields.
[3088] = "Auswählen und bearbeiten",
-- cfb4186c English: Click a condition type to search or browse categories. Dismissing the picker or
--     choosing the same type keeps its fields. Click the condition summary to edit its fields. The
--     chevron switches between name only and summary; the double chevron closes the fields.
[3089] = "Auf einen Bedingungstyp klicken, um zu suchen oder Kategorien zu durchsuchen. Wird die Auswahl geschlossen oder derselbe Typ gewählt, bleiben die Felder erhalten. Auf die Zusammenfassung der Bedingung klicken, um ihre Felder zu bearbeiten. Der Pfeil wechselt zwischen reinem Namen und Zusammenfassung; der Doppelpfeil schließt die Felder.",
-- 0e19bead English: Click a name to rename it. Clear a custom step name to restore its action name.
--     Click a collapsed title to show its summary. Click action or condition text to open its
--     details; the double chevron returns from fields to the summary.
[3090] = "Auf einen Namen klicken, um ihn umzubenennen. Wird ein benutzerdefinierter Schrittname geleert, gilt wieder der Name der Aktion. Auf einen eingeklappten Titel klicken, um seine Zusammenfassung anzuzeigen. Auf den Text einer Aktion oder Bedingung klicken, um die Details zu öffnen; der Doppelpfeil führt von den Feldern zurück zur Zusammenfassung.",
-- 73ff3024 English: Click condition text to edit when this card can run. Enabled / Disabled
--     preserves the card while switching its participation. Actions also require known or carried
--     actions, usable resources, cooldown readiness and valid range.
[3091] = "Auf den Bedingungstext klicken, um festzulegen, wann diese Karte ausgeführt werden kann. Aktiviert / Deaktiviert behält die Karte bei und schaltet nur ihre Teilnahme um. Aktionen erfordern außerdem bekannte oder mitgeführte Aktionen, verfügbare Ressourcen, eine bereite Abklingzeit und eine gültige Reichweite.",
-- 9c1c1630 English: Click the action to edit its type, spell or item. The leading icon previews the
--     effect. Effect selects a style; Magnification changes its size. Click the swatch or edit RGBA
--     on the 0–1 scale. Arrows adjust position; V / H show offsets. Default restores profile
--     values. Sound selection and Play preview an audible reminder.
[3092] = "Auf die Aktion klicken, um ihren Typ, Zauber oder Gegenstand zu bearbeiten. Das vordere Symbol zeigt eine Vorschau des Effekts. Effekt wählt einen Stil; Vergrößerung ändert seine Größe. Auf das Farbfeld klicken oder RGBA auf der Skala 0–1 bearbeiten. Pfeile passen die Position an; V / H zeigen die Versätze. Standard stellt die Profilwerte wieder her. Tonauswahl und Abspielen bieten eine hörbare Erinnerung zur Vorschau.",
-- 3edd382d English: Click the guard text to edit the branch condition. Evaluate uses that
--     condition; Always true / Always false skips it. False is left and red; True is right and
--     green. The branch icon hides both arms without changing them. Click True or False to fold
--     only that arm; its hidden count remains visible. Gray cards in a forced arm are unreachable.
[3093] = "Auf den Wächtertext klicken, um die Bedingung der Verzweigung zu bearbeiten. Auswerten verwendet diese Bedingung; Immer wahr / Immer falsch überspringt sie. Falsch ist links und rot; Wahr ist rechts und grün. Das Verzweigungssymbol blendet beide Zweige aus, ohne sie zu ändern. Auf Wahr oder Falsch klicken, um nur diesen Zweig einzuklappen; die Anzahl der ausgeblendeten Karten bleibt sichtbar. Graue Karten in einem erzwungenen Zweig sind unerreichbar.",
-- 55129537 English: Conditions and state
-- Context: Section title in the rotation editor help for the cards that combine conditions and the
--     state they show.
[3094] = "Bedingungen und Zustand",
-- eacf49cb English: Configure recommendation timing, automatic switching, history, preview and
--     profile highlight defaults. Labels are on the left. Checkboxes toggle options, sliders show
--     numeric values, and fields validate before saving.
[3095] = "Zeitpunkt der Empfehlungen, automatischen Wechsel, Verlauf, Vorschau und Standardwerte für die Profilhervorhebung festlegen. Die Beschriftungen stehen links. Kontrollkästchen schalten Optionen um, Schieberegler zeigen Zahlenwerte, und Felder werden vor dem Speichern geprüft.",
-- 63ee762f English: Drag one card into a highlighted gap; hold Ctrl when starting the drag to carry
--     that card and all following siblings. A branch always carries its children. Use Up / Down on
--     the left to move one card. Duplicate copies the card and the red trash can deletes it.
--     Cooldowns are independent, so they have no move arrows.
[3096] = "Eine Karte in eine hervorgehobene Lücke ziehen; wird beim Ziehen Strg gehalten, werden die Karte und alle folgenden Geschwister mitgenommen. Eine Verzweigung nimmt ihre Kinder immer mit. Mit Hoch / Runter links lässt sich eine einzelne Karte verschieben. Duplizieren kopiert die Karte, der rote Mülleimer löscht sie. Abklingzeiten sind unabhängig und haben daher keine Verschiebepfeile.",
-- 24e03e5b English: Drag a card into one highlighted gap, or use the left-side Up / Down arrows.
--     Hold Ctrl when starting a drag to carry the card and all following siblings. Groups always
--     carry their children. Unavailable moves are gray. Ctrl-click or Shift-click selects several
--     cards for grouping; dragging an existing selection moves that selection. Duplicate copies a
--     card; Split group removes its wrapper; the red trash can deletes it. Add condition and Add
--     group append when clicked or insert where dropped.
[3097] = "Eine Karte in eine hervorgehobene Lücke ziehen oder die Pfeile Hoch / Runter links verwenden. Wird beim Ziehen Strg gehalten, werden die Karte und alle folgenden Geschwister mitgenommen. Gruppen nehmen ihre Kinder immer mit. Nicht mögliche Verschiebungen sind grau. Strg-Klick oder Umschalt-Klick wählt mehrere Karten zum Gruppieren aus; das Ziehen einer bestehenden Auswahl verschiebt diese Auswahl. Duplizieren kopiert eine Karte; Gruppe auflösen entfernt ihre Hülle; der rote Mülleimer löscht sie. Bedingung hinzufügen und Gruppe hinzufügen hängen beim Klicken an oder fügen an der Ablagestelle ein.",
-- adb0a440 English: Editing settings
-- Context: Section title in the settings help: how text fields and the Apply/Discard draft work.
[3098] = "Einstellungen bearbeiten",
-- 1352b3ca English: Highlight effects
-- Context: Section title in the rotation editor help for the highlight effect options of an action
--     card.
[3099] = "Hervorhebungseffekte",
-- fc1e5a5a English: If / Unless toggles negation. Enabled / Disabled keeps the saved fields while
--     skipping evaluation. All / Any changes AND / OR. Click a group name to rename it; the branch
--     icon hides or shows its children. Gray descendants cannot be reached.
[3100] = "Wenn / Außer wenn schaltet die Verneinung um. Aktiviert / Deaktiviert behält die gespeicherten Felder bei, überspringt aber die Auswertung. Alle / Beliebige wechselt zwischen UND / ODER. Auf einen Gruppennamen klicken, um ihn umzubenennen; das Verzweigungssymbol blendet die Kinder aus oder ein. Graue Nachfahren sind unerreichbar.",
-- 0e86051f English: Names and details
-- Context: Section title in the rotation editor help: how to rename steps and open their details.
[3101] = "Namen und Details",
-- e0d1f576 English: Search or filter the rotation roster, then select a rotation. Blue Built In
--     rotations use the same editor but remain read-only; Duplicate makes an editable copy. The
--     name and Metadata describe the rotation. Switch condition selects when it applies. Use the
--     Rotation and Cooldowns tabs to select the content below the switch condition. Cooldowns
--     highlight independently of the ordered rotation.
[3102] = "Die Rotationsliste durchsuchen oder filtern und dann eine Rotation auswählen. Blaue integrierte Rotationen verwenden denselben Editor, bleiben aber schreibgeschützt; Duplizieren erstellt eine bearbeitbare Kopie. Name und Metadaten beschreiben die Rotation. Die Umschaltbedingung legt fest, wann sie gilt. Mit den Reitern Rotation und Abklingzeiten wird der Inhalt unterhalb der Umschaltbedingung ausgewählt. Abklingzeiten werden unabhängig von der geordneten Rotation hervorgehoben.",
-- 42691826 English: The question mark opens full Help for its subject. Hover controls for brief
--     tips. Undo / Redo affect the draft. Apply saves; Discard or Cancel abandons draft changes.
--     Red borders mark invalid or incomplete data.
[3103] = "Das Fragezeichen öffnet die vollständige Hilfe zum jeweiligen Thema. Für kurze Tipps mit der Maus über die Bedienelemente fahren. Rückgängig / Wiederherstellen betreffen den Entwurf. Übernehmen speichert; Verwerfen oder Abbrechen verwirft die Änderungen am Entwurf. Rote Rahmen kennzeichnen ungültige oder unvollständige Daten.",
-- d68ae9c9 English: Using this page
-- Context: Section title at the top of the help for the Functions and Integrations pages: a short
--     guide to the page.
[3104] = "Diese Seite verwenden",
-- 642f28cb English: Version, author, credits and project links are shown here. Click a link field
--     to select its text for copying.
[3105] = "Hier werden Version, Autor, Mitwirkende und Projektlinks angezeigt. Auf ein Linkfeld klicken, um seinen Text zum Kopieren zu markieren.",
-- 9cea69fd English: Window controls
-- Context: Section title in the help: the buttons and controls of the window frame.
[3106] = "Fenstersteuerung",
-- efe10c80 English: Primary
-- Context: Help topic title for the settings made for the first (primary) talent specialization;
--     used only when the game has no word for it.
[3107] = "Primär",
-- 62f2ccff English: Secondary
-- Context: Help topic title for the settings made for the second (secondary) talent specialization;
--     used only when the game has no word for it.
[3108] = "Sekundär",
-- a91d0087 English: Delete category
-- Context: Help topic title in the Conditions help for the Delete category button.
[3109] = "Kategorie löschen",
-- 315dca68 English: Rename the selected category in Manage categories. Built-in categories cannot
--     be renamed or deleted.
[3110] = "Die ausgewählte Kategorie unter Kategorien verwalten umbenennen. Integrierte Kategorien können weder umbenannt noch gelöscht werden.",
-- f6fad90e English: Add an empty named category from the category-management list. Move To in
--     condition settings assigns a condition to it.
[3111] = "Eine leere benannte Kategorie in der Kategorieverwaltung hinzufügen. Verschieben nach in den Bedingungseinstellungen weist ihr eine Bedingung zu.",
-- b31029f7 English: In Manage categories, move the selected category earlier in the category list.
[3112] = "Unter Kategorien verwalten die ausgewählte Kategorie in der Kategorieliste nach vorne verschieben.",
-- 277b5e7b English: In Manage categories, move the selected category later in the category list.
[3113] = "Unter Kategorien verwalten die ausgewählte Kategorie in der Kategorieliste nach hinten verschieben.",
-- 32a806a4 English: Delete a named category after confirmation. Its conditions remain available
--     under Other; their definitions are preserved.
[3114] = "Eine benannte Kategorie nach Bestätigung löschen. Ihre Bedingungen bleiben unter Sonstige verfügbar; ihre Definitionen bleiben erhalten.",
-- e20c9279 English: Filter the visible condition list by name or identifier. The category filter
--     still applies.
[3115] = "Die sichtbare Bedingungsliste nach Name oder Kennung filtern. Der Kategoriefilter gilt weiterhin.",
-- 2715ffec English: Allow this condition type to be used when automatically selecting a rotation.
[3116] = "Diesen Bedingungstyp bei der automatischen Auswahl einer Rotation zulassen.",
-- 91c0665b English: Hide this condition from the Other picker category. Explicit named-category and
--     Switch membership remain available.
[3117] = "Diese Bedingung in der Auswahlkategorie Sonstige ausblenden. Ausdrückliche Zugehörigkeiten zu benannten Kategorien und zu Wechsel bleiben verfügbar.",
-- 4a954399 English: Condition order
-- Context: Help topic title in the Conditions help: how to reorder conditions and categories.
[3118] = "Reihenfolge der Bedingungen",
-- 54375409 English: Apply / Cancel
-- Context: Help topic title for the pair of buttons that save or abandon changes in the announce
--     and effect editors.
[3119] = "Übernehmen / Abbrechen",
-- af06c200 English: Choose a named category or Other, then use Apply beside the destination to
--     stage the move. Page Apply saves all pending changes. Use Switch Condition separately for
--     automatic-switch availability.
[3120] = "Eine benannte Kategorie oder Sonstige wählen und dann Übernehmen neben dem Ziel verwenden, um die Verschiebung vorzumerken. Übernehmen auf der Seite speichert alle ausstehenden Änderungen. Für die Verfügbarkeit beim automatischen Wechsel separat Umschaltbedingung verwenden.",
-- 304b61a5 English: Select several cards
-- Context: Section title in the rotation editor help: how to select more than one rotation card.
[3121] = "Mehrere Karten auswählen",
-- 1e77459b English: Ctrl-click cards to add or remove them from the selection; Shift-click selects
--     the siblings between it and the last clicked card. Shift-drag on empty canvas draws a box
--     that selects every card it touches (Ctrl+Shift-drag adds). With several cards selected, the
--     strip above the canvas groups them as All or Any, and Duplicate, Enable, Disable and Delete
--     act on every selected card; one Undo reverses each. Drag any selected card to move the
--     selection.
[3122] = "Strg-Klick fügt Karten zur Auswahl hinzu oder entfernt sie; Umschalt-Klick wählt die Geschwister zwischen dieser und der zuletzt angeklickten Karte aus. Umschalt-Ziehen auf leerer Arbeitsfläche zieht einen Rahmen auf, der jede berührte Karte auswählt (Strg+Umschalt-Ziehen fügt hinzu). Sind mehrere Karten ausgewählt, gruppiert die Leiste über der Arbeitsfläche sie als Alle oder Beliebige, und Duplizieren, Aktivieren, Deaktivieren und Löschen wirken auf jede ausgewählte Karte; ein einziges Rückgängig macht dies jeweils rückgängig. Eine beliebige ausgewählte Karte ziehen, um die Auswahl zu verschieben.",
-- 47834c1a English: Ctrl-click cards to add or remove them from the selection; Shift-click a title
--     or condition to select the siblings between it and the last clicked card. Shift-drag on empty
--     canvas draws a box that selects every card it touches (Ctrl+Shift-drag adds). Drag any
--     selected card to move the whole selection to one gap. Beside Apply, Duplicate, Enable,
--     Disable and Delete act on every selected card, and one Undo reverses each. Branches keep
--     their Evaluate / Always mode. Click empty canvas to clear the selection.
[3123] = "Strg-Klick fügt Karten zur Auswahl hinzu oder entfernt sie; Umschalt-Klick auf einen Titel oder eine Bedingung wählt die Geschwister zwischen dieser und der zuletzt angeklickten Karte aus. Umschalt-Ziehen auf leerer Arbeitsfläche zieht einen Rahmen auf, der jede berührte Karte auswählt (Strg+Umschalt-Ziehen fügt hinzu). Eine beliebige ausgewählte Karte ziehen, um die gesamte Auswahl in eine Lücke zu verschieben. Neben Übernehmen wirken Duplizieren, Aktivieren, Deaktivieren und Löschen auf jede ausgewählte Karte, und ein einziges Rückgängig macht dies jeweils rückgängig. Verzweigungen behalten ihren Modus Auswerten / Immer. Auf leere Arbeitsfläche klicken, um die Auswahl aufzuheben.",
-- 2c6fdc3c English: Select a profile in the sidebar to inspect it, then Activate profile to switch.
--     New and Duplicate open a named draft with Apply and Cancel. Import stages a validated new
--     profile; Compare shows setting differences. Copy and Reset replace the active profile after
--     confirmation; the red trash deletes an inactive profile.
[3124] = "Ein Profil in der Seitenleiste auswählen, um es anzusehen, und dann mit Profil aktivieren dorthin wechseln. Neu und Duplizieren öffnen einen benannten Entwurf mit Übernehmen und Abbrechen. Importieren merkt ein geprüftes neues Profil vor; Vergleichen zeigt Unterschiede in den Einstellungen. Kopieren und Zurücksetzen ersetzen das aktive Profil nach Bestätigung; der rote Mülleimer löscht ein inaktives Profil.",
-- 80f29cb1 English: The condition ordering controls are arrows and draggable rows in the sidebar of
--     the selected category. In Manage categories, the same controls order the categories
--     themselves.
[3125] = "Die Steuerelemente zur Reihenfolge der Bedingungen sind Pfeile und ziehbare Zeilen in der Seitenleiste der ausgewählten Kategorie. Unter Kategorien verwalten ordnen dieselben Steuerelemente die Kategorien selbst.",
-- fdef8f0b English: Unticked, any rank of the spell matches: a numeric spell selection also
--     recognizes auras with the same readable localized spell name. Ticked, only the exact spell ID
--     you chose matches. Conditions saved before this option keep the exact ID until you untick it.
--     Spell names already match by name. Unavailable metadata or restricted aura identity stays
--     unavailable, including under NOT. Different spells sharing a name can match; tick the option
--     when that distinction matters.
[3126] = "Nicht angehakt stimmt jeder Rang des Zaubers überein: Eine numerische Zauberauswahl erkennt auch Auren mit demselben lesbaren, lokalisierten Zaubernamen. Angehakt stimmt nur die gewählte exakte Zauber-ID überein. Vor dieser Option gespeicherte Bedingungen behalten die exakte ID, bis Sie das Häkchen entfernen. Zaubernamen stimmen bereits nach Namen überein. Nicht verfügbare Metadaten oder eingeschränkte Aura-Identität bleiben nicht verfügbar, auch unter NOT. Verschiedene Zauber mit gleichem Namen können übereinstimmen; setzen Sie das Häkchen, wenn es auf diese Unterscheidung ankommt.",
-- a851dbf4 English: Unticked (the default), any rank of the spell matches. Ticked, only the rank
--     you chose matches.
[3127] = "Nicht angehakt (Standard) stimmt jeder Rang des Zaubers überein. Angehakt stimmt nur der gewählte Rang überein.",
-- 6ef93df0 English: Unticked (the default), any rank of the spell matches. Ticked, only the rank
--     you chose matches, and that rank must be on your action bars.
[3128] = "Nicht angehakt (Standard) stimmt jeder Rang des Zaubers überein. Angehakt stimmt nur der gewählte Rang überein, und dieser Rang muss in Ihren Aktionsleisten liegen.",
-- 5c9c3144 English: A spell picked in the editor is matched by its spell ID, so the condition works
--     on every client language. Conditions saved with a spell name keep matching by that name. If
--     the client cannot read the spell being cast, the condition is unavailable, including under
--     NOT.
[3129] = "Ein im Editor gewählter Zauber wird über seine Zauber-ID abgeglichen, daher funktioniert die Bedingung in jeder Clientsprache. Mit einem Zaubernamen gespeicherte Bedingungen gleichen weiterhin über diesen Namen ab. Kann der Client den gewirkten Zauber nicht lesen, ist die Bedingung nicht verfügbar, auch unter NOT.",
-- c647cb40 English: A spell picked in the editor is matched by its spell ID, so the condition works
--     on every client language. Any rank of that spell matches unless Use this exact spell rank is
--     ticked. Conditions saved with a spell name keep matching by that name. If the client cannot
--     read the spell being cast, the condition is unavailable, including under NOT.
[3130] = "Ein im Editor gewählter Zauber wird über seine Zauber-ID abgeglichen, daher funktioniert die Bedingung in jeder Clientsprache. Jeder Rang dieses Zaubers passt, solange Diesen genauen Zauberrang verwenden nicht aktiviert ist. Mit einem Zaubernamen gespeicherte Bedingungen passen weiterhin über diesen Namen. Kann der Client den gewirkten Zauber nicht lesen, ist die Bedingung nicht verfügbar, auch unter NOT.",
-- 51b10901 English: Navigating rotations
-- Context: Section title in the rotation editor help: zooming, panning and switching views.
[3131] = "In Rotationen navigieren",
-- 35f68027 English: Enabled / Disabled
-- Context: Help topic title in the Announces help for the checkbox that switches an announcement on
--     or off.
[3132] = "Aktiviert / Deaktiviert",
-- 922d8056 English: Announcement substitutions
-- Context: Help topic title in the Announces help: the {{target}}, {{spell}} and {{event}}
--     placeholders that can be put into announcement text.
[3133] = "Ersetzungen in Ankündigungen",
-- 63ff2d53 English: New, Duplicate, Import/Export and Compare
[3134] = "Neu, Duplizieren, Import/Export und Vergleichen",
-- baa6c2fc English: Announcement details stay always expanded while editing. Press Enter or leave a
--     text field to stage its value; Apply saves the draft. Invalid fields must be corrected before
--     Apply; Discard abandons pending changes. Searchable selectors open on click and filter as you
--     type. The page Help icon explains every option and text substitution.
[3135] = "Die Details einer Ankündigung bleiben beim Bearbeiten immer aufgeklappt. Eingabetaste drücken oder ein Textfeld verlassen, um den Wert vorzumerken; Übernehmen speichert den Entwurf. Ungültige Felder müssen vor dem Übernehmen korrigiert werden; Verwerfen verwirft ausstehende Änderungen. Durchsuchbare Auswahllisten öffnen sich per Klick und filtern während der Eingabe. Das Hilfesymbol der Seite erklärt jede Option und jede Textersetzung.",
-- 79d463fa English: Announce selected spell casts or item uses independently of your active
--     rotation, or invoke a configured Via Script/Macro entry directly. Select an entry in the
--     sidebar, or use New to prepare one. The trigger applies to every ordered output card; each
--     card has its own destination and conditions. These settings do not cast spells or use items.
--     Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only
--     clients.
[3136] = "Ausgewählte Zauber oder Gegenstandsbenutzungen unabhängig von der aktiven Rotation ankündigen oder einen konfigurierten Eintrag Per Skript/Makro direkt aufrufen. Einen Eintrag in der Seitenleiste auswählen oder mit Neu einen vorbereiten. Der Auslöser gilt für jede geordnete Ausgabekarte; jede Karte hat ihr eigenes Ziel und ihre eigenen Bedingungen. Diese Einstellungen wirken keine Zauber und benutzen keine Gegenstände. Durch Zauber ausgelöste Ankündigungen folgen den Kampfdatenrichtlinien von RM und laufen nicht auf reinen Referenz-Clients.",
-- 405280cc English: An optional name identifies this announcement in the sidebar. Without one, the
--     action name or Via Script/Macro identifier is used. Changing this display name does not
--     change the watched action or callable identifier.
[3137] = "Ein optionaler Name kennzeichnet diese Ankündigung in der Seitenleiste. Ohne Namen wird der Aktionsname oder die Kennung von Per Skript/Makro verwendet. Eine Änderung dieses Anzeigenamens ändert weder die überwachte Aktion noch die aufrufbare Kennung.",
-- d90e5cae English: Choose Spell, Pet Spell, Item or Via Script/Macro. Changing type clears the
--     previous action and exact-rank choice. Via Script/Macro uses an Identifier instead of a cast
--     event or stored action; switching back restores the event selector. Choosing the current type
--     keeps its fields.
[3138] = "Zauber, Begleiterzauber, Gegenstand oder Per Skript/Makro wählen. Ein Typwechsel löscht die bisherige Aktion und die Wahl des exakten Rangs. Per Skript/Makro verwendet eine Kennung statt eines Zauberereignisses oder einer gespeicherten Aktion; beim Zurückwechseln erscheint die Ereignisauswahl wieder. Wird der aktuelle Typ gewählt, bleiben seine Felder erhalten.",
-- 198d0d82 English: Watch one of your spells. Choose the spell in the searchable field below Action
--     Type.
[3139] = "Einen Ihrer Zauber überwachen. Den Zauber im durchsuchbaren Feld unter Aktionstyp wählen.",
-- bb010073 English: Watch a spell from your pet spellbook. The spell selector uses the pet catalog
--     for this action type.
[3140] = "Einen Zauber aus dem Zauberbuch des Begleiters überwachen. Die Zauberauswahl verwendet für diesen Aktionstyp den Begleiterkatalog.",
-- c331b8d1 English: Watch item-use spells from a reusable item set or a custom list. This is an
--     announcement trigger; it does not choose an item to use for you.
[3141] = "Gegenstandsbenutzungszauber aus einem wiederverwendbaren Gegenstandsset oder einer eigenen Liste überwachen. Dies ist ein Auslöser für Ankündigungen; es wird kein Gegenstand zur Benutzung ausgewählt.",
-- 6e216ab8 English: Search by spell name, select a result, or drag a spell from your spellbook or
--     action bar into the field. The icon and name identify the selected spell. Spell and pet spell
--     choices keep their respective catalog scope.
[3142] = "Nach Zaubernamen suchen, ein Ergebnis auswählen oder einen Zauber aus dem Zauberbuch oder der Aktionsleiste in das Feld ziehen. Symbol und Name kennzeichnen den ausgewählten Zauber. Zauber und Begleiterzauber behalten jeweils ihren eigenen Katalogbereich.",
-- 691e05e6 English: Unchecked (the default), any known rank of the spell matches. Checked limits
--     matching to the rank you chose. This checkbox is shown only for Spell and Pet Spell, and only
--     on clients with spell ranks.
[3143] = "Nicht angehakt (Standard) stimmt jeder bekannte Rang des Zaubers überein. Angehakt beschränkt die Übereinstimmung auf den gewählten Rang. Dieses Kontrollkästchen wird nur für Zauber und Begleiterzauber angezeigt, und nur auf Clients mit Zauberrängen.",
-- c75f5c21 English: Choose a reusable set, or Custom to edit this announcement's own list. For a
--     custom list, search for or drag items into the fields; Add item appends one and a red trash
--     can removes an entry. Any matching item-use spell in the list can trigger the announcement;
--     list order does not limit announcements to the first carried item. Changes to a shared set
--     belong on the Item Sets page.
[3144] = "Ein wiederverwendbares Set wählen oder Benutzerdefiniert, um die eigene Liste dieser Ankündigung zu bearbeiten. Bei einer eigenen Liste Gegenstände in die Felder suchen oder ziehen; Gegenstand hinzufügen hängt einen an, der rote Mülleimer entfernt einen Eintrag. Jeder passende Gegenstandsbenutzungszauber in der Liste kann die Ankündigung auslösen; die Listenreihenfolge beschränkt Ankündigungen nicht auf den ersten mitgeführten Gegenstand. Änderungen an einem gemeinsamen Set gehören auf die Seite Gegenstandssets.",
-- 09fd4592 English: For automatic action types, choose which observed cast event triggers this
--     entry. A start, stop, interruption, failure or delay is different from a successful cast.
--     Client support determines which events and observations are available. Via Script/Macro has
--     no cast event.
[3145] = "Bei automatischen Aktionstypen wählen, welches beobachtete Zauberereignis diesen Eintrag auslöst. Ein Beginn, Ende, eine Unterbrechung, ein Fehlschlag oder eine Verzögerung ist etwas anderes als ein erfolgreich gewirkter Zauber. Welche Ereignisse und Beobachtungen verfügbar sind, hängt vom Client ab. Per Skript/Makro hat kein Zauberereignis.",
-- d9dcc847 English: The cast or channel started. This event does not mean it will finish
--     successfully.
[3146] = "Das Wirken oder Kanalisieren hat begonnen. Dieses Ereignis bedeutet nicht, dass es erfolgreich abgeschlossen wird.",
-- 2e1b963f English: The cast or channel stopped. A stop alone does not establish whether it
--     succeeded.
[3147] = "Das Wirken oder Kanalisieren wurde beendet. Ein Ende allein sagt nicht aus, ob es erfolgreich war.",
-- 37c82b71 English: The client reported a successful spell cast or item-use spell. For a channel,
--     this can occur as channeling begins rather than after its final tick.
[3148] = "Der Client hat einen erfolgreich gewirkten Zauber oder Gegenstandsbenutzungszauber gemeldet. Bei einem kanalisierten Zauber kann dies schon zu Beginn der Kanalisierung statt nach dem letzten Tick eintreten.",
-- 94a29d0b English: The client reported that the cast was interrupted. This can include canceling a
--     cast yourself.
[3149] = "Der Client hat gemeldet, dass das Wirken unterbrochen wurde. Dazu kann auch das eigene Abbrechen eines Zaubers gehören.",
-- 7c5f19c7 English: The client reported that the cast failed. This is separate from the
--     successful-cast event.
[3150] = "Der Client hat gemeldet, dass das Wirken fehlgeschlagen ist. Dies ist vom Ereignis für erfolgreiches Wirken getrennt.",
-- 9ae70605 English: The client reported a delay to the cast. This event is not a completion or
--     success notification.
[3151] = "Der Client hat eine Verzögerung des Wirkens gemeldet. Dieses Ereignis ist keine Meldung über Abschluss oder Erfolg.",
-- 326e2b60 English: Choose a chat destination, local output, a named Emote or Audible. Emote
--     replaces Text with an emote selector and optional recipient. Audible replaces Text with
--     Sound. Text is retained when switching modes. Say, Yell, Whisper and named joined channels
--     are offered only for Via Script/Macro and remain subject to native restrictions.
[3152] = "Ein Chatziel, die lokale Ausgabe, ein benanntes Emote oder Hörbar wählen. Emote ersetzt Text durch eine Emote-Auswahl und einen optionalen Empfänger. Hörbar ersetzt Text durch Ton. Der Text bleibt beim Wechseln des Modus erhalten. Sagen, Schreien, Flüstern und benannte beigetretene Kanäle werden nur für Per Skript/Makro angeboten und unterliegen weiterhin den Einschränkungen des Spiels.",
-- 8352df04 English: Play the selected sound locally on the Master audio channel; no chat message is
--     sent. Choose an available sound before applying the announcement.
[3153] = "Den ausgewählten Ton lokal über den Master-Audiokanal abspielen; es wird keine Chatnachricht gesendet. Vor dem Übernehmen der Ankündigung einen verfügbaren Ton wählen.",
-- b952981f English: Use raid chat while in a raid, party chat while in a party, or your local chat
--     frame while solo.
[3154] = "Im Schlachtzug den Schlachtzugchat, in einer Gruppe den Gruppenchat und allein das lokale Chatfenster verwenden.",
-- 0048ad2e English: Use party chat when grouped, including your party within a raid. This
--     destination produces no solo chat message.
[3155] = "In einer Gruppe den Gruppenchat verwenden, auch für die eigene Gruppe innerhalb eines Schlachtzugs. Allein erzeugt dieses Ziel keine Chatnachricht.",
-- 4dd62130 English: Request group warning output. Depending on group membership and permissions, RM
--     may use raid chat, party chat, or local output instead.
[3156] = "Eine Gruppenwarnung anfordern. Je nach Gruppenzugehörigkeit und Berechtigungen verwendet RM stattdessen den Schlachtzugchat, den Gruppenchat oder die lokale Ausgabe.",
-- 5a88e05c English: A saved free-text emote keeps its original message. Select Emote to use a named
--     client emote instead.
[3157] = "Ein gespeichertes Freitext-Emote behält seine ursprüngliche Nachricht. Emote wählen, um stattdessen ein benanntes Client-Emote zu verwenden.",
-- 0bab8021 English: Choose a named emote from this client's slash commands, such as /cheer. This
--     does not send the Text field as a custom emote.
[3158] = "Ein benanntes Emote aus den Slash-Befehlen dieses Clients wählen, etwa /cheer. Dabei wird das Textfeld nicht als eigenes Emote gesendet.",
-- a7a449d8 English: Choose the emote to perform when the configured cast event is observed. The
--     client may restrict an emote or require a hardware action; RM does not retry through another
--     output path.
[3159] = "Das Emote wählen, das ausgeführt wird, wenn das konfigurierte Zauberereignis beobachtet wird. Der Client kann ein Emote einschränken oder eine Hardwareaktion verlangen; RM versucht es nicht erneut über einen anderen Ausgabeweg.",
-- 7c9bf8c3 English: For cast entries, checked directs the emote to the recipient recorded for this
--     exact cast, including click casting. It does not use your current target or a previous cast's
--     recipient. For Via Script/Macro, checked uses the supplied macro unit. A missing recipient
--     skips targeted output. Unchecked performs the emote without a target.
[3160] = "Bei Zaubereinträgen richtet Aktiviert das Emote an den für genau diesen Zauber erfassten Empfänger, auch beim Klickzaubern. Es wird weder das aktuelle Ziel noch der Empfänger eines früheren Zaubers verwendet. Bei Per Skript/Makro verwendet Aktiviert die übergebene Makro-Einheit. Fehlt ein Empfänger, entfällt die gezielte Ausgabe. Deaktiviert führt das Emote ohne Ziel aus.",
-- 24d388c2 English: Write to your own chat frame. Other players do not receive this message.
[3161] = "In das eigene Chatfenster schreiben. Andere Spieler erhalten diese Nachricht nicht.",
-- 2224d247 English: Enter the message for a chat destination. The substitutions below insert action
--     and cast information when it is available. This text is not used for Audible or named Emote
--     output.
[3162] = "Die Nachricht für ein Chatziel eingeben. Die unten aufgeführten Ersetzungen fügen Informationen zu Aktion und Zauber ein, sofern verfügbar. Dieser Text wird für Hörbar und benannte Emotes nicht verwendet.",
-- 5625f190 English: For cast entries, {{spell}} is a spell link, {{item}} an item link and
--     {{event}} the localized event name. {{target}} uses the recorded cast target, with the last
--     recorded target for that spell as a fallback; it does not automatically use your selected
--     target or your name. Unavailable cast substitutions can remain unchanged. Via Script/Macro
--     instead uses its supplied target and spell, {{event}} becomes Via Script/Macro, and required
--     missing inputs skip output; this API supplies no {{item}}.
[3163] = "Bei Zaubereinträgen ist {{spell}} ein Zauberlink, {{item}} ein Gegenstandslink und {{event}} der lokalisierte Ereignisname. {{target}} verwendet das erfasste Ziel des Zaubers, ersatzweise das zuletzt erfasste Ziel dieses Zaubers; es verwendet nicht automatisch Ihr ausgewähltes Ziel oder Ihren Namen. Nicht verfügbare Zauberersetzungen können unverändert bleiben. Per Skript/Makro verwendet stattdessen das übergebene Ziel und den übergebenen Zauber, {{event}} wird zu Per Skript/Makro, und fehlen erforderliche Eingaben, entfällt die Ausgabe; diese API liefert kein {{item}}.",
-- a7af0c5c English: Choose a sound supplied by the shared-media catalog, then click Play to preview
--     it. Preview is local and does not save the draft. An unavailable sound cannot be previewed;
--     Audible announcements require a nonempty sound selection.
[3164] = "Einen Ton aus dem Shared-Media-Katalog wählen und dann zur Vorschau auf Abspielen klicken. Die Vorschau ist lokal und speichert den Entwurf nicht. Ein nicht verfügbarer Ton kann nicht vorgehört werden; hörbare Ankündigungen erfordern eine nicht leere Tonauswahl.",
-- 58fc69dd English: The pill turns this entry on or off while keeping its fields. Disabled entries
--     do not announce matching casts or macro invocations. Apply saves the changed state.
[3165] = "Der Schalter aktiviert oder deaktiviert diesen Eintrag und behält dabei seine Felder. Deaktivierte Einträge kündigen passende Zauber oder Makroaufrufe nicht an. Übernehmen speichert den geänderten Zustand.",
-- 2ca49225 English: Edits stay in a draft until Apply. Complete the action or Via Script/Macro
--     identifier and other required fields before saving. Discard abandons changes to saved
--     announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply,
--     Discard or Cancel navigation.
[3166] = "Bearbeitungen bleiben bis zum Übernehmen in einem Entwurf. Vor dem Speichern die Aktion bzw. die Kennung von Per Skript/Makro und die übrigen Pflichtfelder ausfüllen. Verwerfen verwirft Änderungen an gespeicherten Ankündigungen; Abbrechen schließt einen neuen Erstellungsentwurf. Beim Verlassen mit ausstehenden Änderungen werden Übernehmen, Verwerfen oder Abbrechen angeboten.",
-- af92b7de English: Use the sidebar buttons to create, duplicate, transfer or compare
--     announcements. Apply saves the imported draft; Compare does not merge entries. Via
--     Script/Macro Duplicate assigns a distinct identifier and every copied output gets a fresh
--     identity. Series exports use version 2; version 1 remains available for legacy single-output
--     entries. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes
--     the selected saved entry after confirmation. Resolve pending edits first; deletion does not
--     carry into the next selected draft.
[3167] = "Mit den Schaltflächen der Seitenleiste Ankündigungen erstellen, duplizieren, übertragen oder vergleichen. Übernehmen speichert den importierten Entwurf; Vergleichen führt keine Einträge zusammen. Duplizieren bei Per Skript/Makro vergibt eine eigene Kennung, und jede kopierte Ausgabe erhält eine neue Identität. Serienexporte verwenden Version 2; Version 1 bleibt für ältere Einträge mit nur einer Ausgabe verfügbar. Importe und Übernehmen lehnen mehrdeutige Kennungen ab. Der rote Mülleimer löscht den ausgewählten gespeicherten Eintrag nach Bestätigung endgültig. Zuerst ausstehende Bearbeitungen erledigen; das Löschen wird nicht in den nächsten ausgewählten Entwurf übernommen.",
-- 2aefc10f English: An item set is an ordered list of alternatives, such as different mana potions.
--     Runtime selection checks the list from the top for a carried or, where requested, equipped
--     item. Priority comes from the order you choose, not the item level. Selecting an item does
--     not by itself prove that it is usable, off cooldown, or in range; action readiness is checked
--     separately.
[3168] = "Ein Gegenstandsset ist eine geordnete Liste von Alternativen, etwa verschiedenen Manatränken. Bei der Auswahl zur Laufzeit wird die Liste von oben nach einem mitgeführten oder, falls verlangt, angelegten Gegenstand durchsucht. Die Priorität ergibt sich aus der gewählten Reihenfolge, nicht aus der Gegenstandsstufe. Die Auswahl eines Gegenstands beweist allein noch nicht, dass er benutzbar, nicht auf Abklingzeit oder in Reichweite ist; die Bereitschaft der Aktion wird gesondert geprüft.",
-- f684e8a2 English: Name the selected set so it can be found in the sidebar and referenced by
--     rotations or conditions. New opens a name form; its first Apply saves an empty named set. Add
--     items afterward and Apply again to save them. Discarding later item edits keeps that already
--     saved set. Renaming a set does not change its identity in saved references.
[3169] = "Dem ausgewählten Set einen Namen geben, damit es in der Seitenleiste gefunden und von Rotationen oder Bedingungen referenziert werden kann. Neu öffnet ein Namensformular; das erste Übernehmen speichert ein leeres benanntes Set. Danach Gegenstände hinzufügen und erneut übernehmen, um sie zu speichern. Werden spätere Gegenstandsänderungen verworfen, bleibt das bereits gespeicherte Set erhalten. Das Umbenennen eines Sets ändert seine Identität in gespeicherten Verweisen nicht.",
-- 21312192 English: Checked stores this set in the shared global collection, available to other
--     profiles and characters using this addon database. Unchecked stores it in the current
--     profile, which can itself be shared by characters. This is a staged move; Apply saves it. A
--     profile set takes precedence if a global set has the same saved identity.
[3170] = "Aktiviert speichert dieses Set in der gemeinsamen globalen Sammlung, die anderen Profilen und Charakteren mit dieser Addon-Datenbank zur Verfügung steht. Deaktiviert speichert es im aktuellen Profil, das seinerseits von mehreren Charakteren genutzt werden kann. Dies ist eine vorgemerkte Verschiebung; Übernehmen speichert sie. Ein Profilset hat Vorrang, wenn ein globales Set dieselbe gespeicherte Identität hat.",
-- 0ba4e811 English: The list of item cards is the priority order. Put preferred items first. RM can
--     leave a selection unavailable when required inventory or identity observations are missing;
--     it does not treat unknown data as proof that a lower-priority item should be used. The
--     sidebar icon represents the first defined item and need not be the currently carried or
--     highlighted one.
[3171] = "Die Liste der Gegenstandskarten ist die Prioritätsreihenfolge. Bevorzugte Gegenstände nach vorn stellen. RM kann eine Auswahl als nicht verfügbar belassen, wenn erforderliche Inventar- oder Identitätsbeobachtungen fehlen; unbekannte Daten gelten nicht als Beweis, dass ein Gegenstand mit niedrigerer Priorität verwendet werden sollte. Das Symbol in der Seitenleiste steht für den ersten definierten Gegenstand und muss nicht der aktuell mitgeführte oder hervorgehobene sein.",
-- a5bf7ef1 English: Search by item name and choose a result, or drag an item from your bags or
--     action bar into its field. The icon identifies the item; metadata can take time to load. Edit
--     a row to replace that entry. Use its red trash can to remove it rather than clearing a
--     required item field.
[3172] = "Nach Gegenstandsnamen suchen und ein Ergebnis wählen oder einen Gegenstand aus den Taschen oder der Aktionsleiste in sein Feld ziehen. Das Symbol kennzeichnet den Gegenstand; das Laden der Metadaten kann etwas dauern. Eine Zeile bearbeiten, um diesen Eintrag zu ersetzen. Zum Entfernen den roten Mülleimer verwenden, statt ein Pflichtfeld für den Gegenstand zu leeren.",
-- 67b1eae9 English: Choose or drag an item into the empty item field above the list, then click Add
--     item to append it to the priority list, or drag Add item into a gap between cards to insert
--     it there. Entering an item in this field alone does not add a row.
[3173] = "Einen Gegenstand in das leere Gegenstandsfeld über der Liste wählen oder ziehen und dann auf Gegenstand hinzufügen klicken, um ihn an die Prioritätenliste anzuhängen, oder Gegenstand hinzufügen in eine Lücke zwischen Karten ziehen, um ihn dort einzufügen. Ein Eintrag in diesem Feld allein fügt noch keine Zeile hinzu.",
-- 50b0f89c English: Move Up / Move Down
[3174] = "Nach oben / Nach unten",
-- 69b751c9 English: Use the arrows on the left, or drag an item row into a highlighted insertion
--     gap. Ctrl-drag moves that row and all following entries together. The floating preview
--     identifies what you are moving. Moves past the beginning or end are unavailable. Reordering
--     changes priority and stays in the draft until Apply.
[3175] = "Die Pfeile links verwenden oder eine Gegenstandszeile in eine hervorgehobene Einfügelücke ziehen. Strg-Ziehen verschiebt diese Zeile zusammen mit allen folgenden Einträgen. Die schwebende Vorschau zeigt, was verschoben wird. Verschiebungen über den Anfang oder das Ende hinaus sind nicht möglich. Das Umsortieren ändert die Priorität und bleibt bis zum Übernehmen im Entwurf.",
-- 2b906316 English: Bind / Unbind
-- Context: Help topic title in the item set help for the buttons that connect an item set to a
--     macro/action button or remove the link.
[3176] = "Binden / Bindung lösen",
-- 81abb5f4 English: Outside combat, apply pending item-set edits before binding. Drag the set (its
--     row in the list, or the Bind pill) onto any action bar slot; an occupied slot swaps, leaving
--     its previous action on the cursor. Or click Bind and then click an empty slot. Both pick up
--     the first available item of the set. RM records the slot and updates it as item availability
--     changes. The pill shows bound slot numbers; click it to unbind and remove still-matching bar
--     items. Replaced bar actions are preserved. Binding changes are immediate action-bar
--     operations, independent of the draft and its history.
[3177] = "Außerhalb des Kampfes vor dem Binden ausstehende Änderungen am Gegenstandsset übernehmen. Das Set (seine Zeile in der Liste oder die Marke Binden) auf einen beliebigen Aktionsleistenplatz ziehen; bei einem belegten Platz wird getauscht, und die bisherige Aktion bleibt am Mauszeiger. Oder auf Binden und danach auf einen leeren Platz klicken. Beides nimmt den ersten verfügbaren Gegenstand des Sets auf. RM merkt sich den Platz und aktualisiert ihn, wenn sich die Verfügbarkeit der Gegenstände ändert. Die Marke zeigt die Nummern der gebundenen Plätze; ein Klick darauf löst die Bindung und entfernt noch passende Gegenstände von der Leiste. Ersetzte Leistenaktionen bleiben erhalten. Bindungsänderungen sind sofortige Vorgänge an der Aktionsleiste, unabhängig vom Entwurf und seinem Verlauf.",
-- 7c8417f1 English: Restore the packaged item list for this set. Reset is available only for a set
--     with a packaged default. The restored list is staged until Apply; the name is kept.
[3178] = "Die mitgelieferte Gegenstandsliste dieses Sets wiederherstellen. Zurücksetzen ist nur für ein Set mit mitgeliefertem Standard verfügbar. Die wiederhergestellte Liste bleibt bis zum Übernehmen vorgemerkt; der Name bleibt erhalten.",
-- 70b9c94e English: The red trash can at the top right permanently removes the selected saved set
--     after confirmation. Resolve pending edits before the final warning. References in rotations
--     or conditions then need another set. Deletion reconciles still-matching bound bar actions and
--     keeps the set if unbinding fails; the next selection opens without an unsaved deletion
--     marker.
[3179] = "Der rote Mülleimer oben rechts entfernt das ausgewählte gespeicherte Set nach Bestätigung endgültig. Ausstehende Bearbeitungen vor der letzten Warnung erledigen. Verweise in Rotationen oder Bedingungen benötigen danach ein anderes Set. Beim Löschen werden noch passende gebundene Leistenaktionen abgeglichen, und das Set bleibt erhalten, wenn das Lösen der Bindung fehlschlägt; die nächste Auswahl öffnet sich ohne ungespeicherte Löschmarkierung.",
-- 49c1588e English: Undo / Redo
-- Context: Help topic title in the item set help for the undo and redo buttons.
[3180] = "Rückgängig / Wiederherstellen",
-- cd68dbfd English: Undo and Redo travel through recent item-set draft edits, including
--     replacements, additions, ordering and row removals. They are unavailable when that direction
--     has no history. Apply, Discard or leaving the page clears this bounded history. They do not
--     reverse confirmed entity deletion or explicit action-bar binding operations.
[3181] = "Rückgängig und Wiederherstellen durchlaufen die letzten Entwurfsänderungen am Gegenstandsset, einschließlich Ersetzungen, Hinzufügungen, Reihenfolge und entfernter Zeilen. Sie sind nicht verfügbar, wenn es in dieser Richtung keinen Verlauf gibt. Übernehmen, Verwerfen oder Verlassen der Seite löscht diesen begrenzten Verlauf. Bestätigte Löschungen und ausdrückliche Bindungsvorgänge an der Aktionsleiste werden nicht rückgängig gemacht.",
-- 68ab50bb English: Ordinary item-set edits stay in a draft until Apply. Discard restores the saved
--     item sets. Cancel closes a new creation draft. Leaving with pending changes offers Apply,
--     Discard or Cancel navigation. Invalid fields must be corrected before Apply; Discard can
--     abandon them.
[3182] = "Normale Änderungen am Gegenstandsset bleiben bis zum Übernehmen in einem Entwurf. Verwerfen stellt die gespeicherten Gegenstandssets wieder her. Abbrechen schließt einen neuen Erstellungsentwurf. Beim Verlassen mit ausstehenden Änderungen werden Übernehmen, Verwerfen oder Abbrechen angeboten. Ungültige Felder müssen vor dem Übernehmen korrigiert werden; Verwerfen kann sie verwerfen.",
-- b81b94df English: Use the buttons below the sidebar to create, duplicate, transfer, or compare
--     sets. Duplicate makes an independent profile copy. Import shows the source name and can
--     create a renamed copy or replace the selected list; Apply saves the staged result. Compare
--     inspects differences without merging or modifying either set.
[3183] = "Mit den Schaltflächen unter der Seitenleiste Sets erstellen, duplizieren, übertragen oder vergleichen. Duplizieren erstellt eine unabhängige Profilkopie. Importieren zeigt den Quellnamen und kann eine umbenannte Kopie erstellen oder die ausgewählte Liste ersetzen; Übernehmen speichert das vorgemerkte Ergebnis. Vergleichen zeigt Unterschiede, ohne eines der Sets zusammenzuführen oder zu ändern.",
-- 147db4bf English: Legacy macro buttons
-- Context: Help topic title in the item set help: older macro buttons made before the current
--     system.
[3184] = "Alte Makro-Schaltflächen",
-- 77908784 English: Legacy clients may allow /click to invoke an RM item-set button separately from
--     action-bar binding. The name is RM_ followed by the set name with non-alphanumeric characters
--     removed, then an underscore and unit token. For a set named Bandages, an example is /click
--     [@mouseover,nodead,help] RM_Bandages_mouseover. Other unit suffixes include player, pet,
--     target, focus, pettarget, targettarget, focustarget, and mouseovertarget. These buttons
--     contain item-use macro lines and do not provide the same readiness or first-item guarantee as
--     the recommendation engine. Availability is subject to the client's secure-button and macro
--     restrictions; reference-only support does not promise executable macro buttons.
[3185] = "Ältere Clients erlauben eventuell, eine Gegenstandsset-Schaltfläche von RM unabhängig von der Aktionsleistenbindung mit /click aufzurufen. Der Name besteht aus RM_, gefolgt vom Setnamen ohne nicht-alphanumerische Zeichen, dann einem Unterstrich und der Einheitenkennung. Für ein Set namens Bandages lautet ein Beispiel /click [@mouseover,nodead,help] RM_Bandages_mouseover. Weitere Einheitensuffixe sind player, pet, target, focus, pettarget, targettarget, focustarget und mouseovertarget. Diese Schaltflächen enthalten Makrozeilen zur Gegenstandsbenutzung und bieten nicht dieselbe Garantie für Bereitschaft oder ersten Gegenstand wie die Empfehlungs-Engine. Die Verfügbarkeit unterliegt den Einschränkungen des Clients für sichere Schaltflächen und Makros; reine Referenzunterstützung verspricht keine ausführbaren Makro-Schaltflächen.",
-- 0378c27f English: Search for an item or drag it into the item field or icon. Choose the result to
--     retain its exact item identity. The icon and name may be unavailable until metadata loads.
--     Field clearing and save behavior belong to the editor that contains this list; use Delete
--     when you intend to remove an entry.
[3186] = "Nach einem Gegenstand suchen oder ihn in das Gegenstandsfeld oder auf das Symbol ziehen. Das Ergebnis wählen, um die exakte Gegenstandsidentität zu übernehmen. Symbol und Name sind eventuell erst nach dem Laden der Metadaten verfügbar. Das Leeren von Feldern und das Speichern regelt der Editor, der diese Liste enthält; Löschen verwenden, wenn ein Eintrag entfernt werden soll.",
-- 6a348c09 English: Move this entry to the first position in the item priority list, when that
--     control is offered.
[3187] = "Diesen Eintrag an die erste Stelle der Gegenstandsprioritätenliste verschieben, sofern dieses Steuerelement angeboten wird.",
-- 3b1a1705 English: Move this entry one position earlier. A move before the first entry is
--     unavailable.
[3188] = "Diesen Eintrag eine Position nach vorn verschieben. Vor den ersten Eintrag ist keine Verschiebung möglich.",
-- a147318d English: Move this entry one position later. A move past the final entry is unavailable.
[3189] = "Diesen Eintrag eine Position nach hinten verschieben. Hinter den letzten Eintrag ist keine Verschiebung möglich.",
-- 4b77e29f English: Move this entry to the final position in the item priority list, when that
--     control is offered.
[3190] = "Diesen Eintrag an die letzte Stelle der Gegenstandsprioritätenliste verschieben, sofern dieses Steuerelement angeboten wird.",
-- 0c112c0c English: Remove this entry from the list. In a draft editor this remains pending until
--     Apply, and Discard abandons the row edit. Undo is available where the containing editor
--     provides draft history. This differs from permanently deleting the entire set after
--     confirmation.
[3191] = "Diesen Eintrag aus der Liste entfernen. In einem Entwurfseditor bleibt dies bis zum Übernehmen ausstehend, und Verwerfen verwirft die Zeilenänderung. Rückgängig ist verfügbar, wo der umgebende Editor einen Entwurfsverlauf bietet. Dies unterscheidet sich vom endgültigen Löschen des gesamten Sets nach Bestätigung.",
-- df1955d5 English: Use All, Built In or Custom to choose the condition source, then filter by
--     Switch, Other or a named category. Search above these controls narrows the visible list
--     without changing assignments.
[3192] = "Mit Alle, Integriert oder Benutzerdefiniert die Herkunft der Bedingungen wählen und dann nach Wechsel, Sonstige oder einer benannten Kategorie filtern. Die Suche über diesen Steuerelementen schränkt die sichtbare Liste ein, ohne Zuordnungen zu ändern.",
-- 190e427d English: Open Manage categories below the list for category maintenance. Manage
--     conditions returns to individual condition settings.
[3193] = "Kategorien verwalten unterhalb der Liste öffnen, um Kategorien zu pflegen. Bedingungen verwalten kehrt zu den Einstellungen der einzelnen Bedingung zurück.",
-- a9dcdfe2 English: Below the condition list, Import/Export opens the selected custom definition
--     for transfer and code review; it is disabled for built-in conditions. In Manage categories,
--     transfer a category’s ordered condition identifiers. Named categories and Other are exclusive
--     destinations. Switch membership is independent.
[3194] = "Unter der Bedingungsliste öffnet Import/Export die ausgewählte benutzerdefinierte Definition zur Übertragung und Codeprüfung; für integrierte Bedingungen ist es deaktiviert. Unter Kategorien verwalten lassen sich die geordneten Bedingungskennungen einer Kategorie übertragen. Benannte Kategorien und Sonstige schließen sich als Ziel gegenseitig aus. Die Zugehörigkeit zu Wechsel ist davon unabhängig.",
-- 936a161c English: Editor
-- Context: Help topic title in Integrations settings help for the Lua editor options.
[3195] = "Editor",
-- 0c601351 English: Optional addons
-- Context: Help topic title in Integrations help: the list of other addons Rotation Master can work
--     with.
[3196] = "Optionale Addons",
-- 0413ac9a English: Undo and Redo edit the Lua body. Reset restores the saved body or new-function
--     template and can be undone. Check syntax executes no custom Lua. Apply saves the body and
--     metadata together; Discard abandons the draft. Leaving with changes offers Apply, Discard or
--     Cancel.
[3197] = "Rückgängig und Wiederherstellen bearbeiten den Lua-Code. Zurücksetzen stellt den gespeicherten Code oder die Vorlage für neue Funktionen wieder her und kann rückgängig gemacht werden. Syntax prüfen führt kein benutzerdefiniertes Lua aus. Übernehmen speichert Code und Metadaten gemeinsam; Verwerfen verwirft den Entwurf. Beim Verlassen mit Änderungen werden Übernehmen, Verwerfen oder Abbrechen angeboten.",
-- 5e86a29a English: Include custom function dependencies exports their source with the selected
--     definition. Without it, the bundle records required helper identities and versions. Review
--     source shows every imported Lua body. Resolve each original name and destination with Reuse,
--     Replace or a new identifier. Apply import saves the complete reviewed bundle and can register
--     imported Lua. Only apply code you trust.
[3198] = "Abhängigkeiten von benutzerdefinierten Funktionen einschließen exportiert deren Quellcode zusammen mit der ausgewählten Definition. Ohne diese Option vermerkt das Paket nur Identität und Version der benötigten Hilfsfunktionen. Quellcode prüfen zeigt jeden importierten Lua-Code. Für jeden ursprünglichen Namen und jedes Ziel Wiederverwenden, Ersetzen oder eine neue Kennung wählen. Import übernehmen speichert das vollständige geprüfte Paket und kann importiertes Lua registrieren. Nur vertrauenswürdigen Code übernehmen.",
-- b696d1d1 English: Arguments and returns
-- Context: Section title in the Functions help: how the Arguments and Returns lists work.
[3199] = "Argumente und Rückgabewerte",
-- 2be54423 English: Choose an existing namespace from the suggestions or type a new dotted
--     namespace. Built In namespaces follow source files; custom namespaces are implied by saved
--     functions and need no separate maintenance.
[3200] = "Einen vorhandenen Namensraum aus den Vorschlägen wählen oder einen neuen Namensraum mit Punkten eingeben. Integrierte Namensräume folgen den Quelldateien; benutzerdefinierte Namensräume ergeben sich aus gespeicherten Funktionen und erfordern keine eigene Pflege.",
-- f6a949d3 English: Function names use letters, numbers and underscores, beginning with a letter or
--     underscore. The code signature shows the qualified namespace.name used by callers.
[3201] = "Funktionsnamen bestehen aus Buchstaben, Ziffern und Unterstrichen und beginnen mit einem Buchstaben oder Unterstrich. Die Codesignatur zeigt den qualifizierten namespace.name, den Aufrufer verwenden.",
-- 330af7d6 English: Search helpers by name or description, then filter Built In / Custom and
--     namespace. Packaged helpers use the same read-only pane. Duplicate creates an editable custom
--     copy.
[3202] = "Hilfsfunktionen nach Name oder Beschreibung durchsuchen und dann nach Integriert / Benutzerdefiniert und Namensraum filtern. Mitgelieferte Hilfsfunktionen verwenden denselben schreibgeschützten Bereich. Duplizieren erstellt eine bearbeitbare benutzerdefinierte Kopie.",
-- e67ec7ba English: Click an Arguments or Returns heading to collapse or expand it. + Argument and
--     + Return append when clicked, or insert at a highlighted gap when dragged. Drag a row or use
--     Up / Down to reorder; Ctrl-drag carries following rows. The trash can removes a row. Type and
--     Nullable document accepted values; Description explains each input or result. Lua can return
--     several ordered results. Return rows describe those results; moving them does not rewrite
--     return statements. Reordering a saved function warns because positional callers may need
--     changes; RM does not rewrite call sites.
[3203] = "Auf eine Überschrift Argumente oder Rückgabewerte klicken, um sie ein- oder auszuklappen. + Argument und + Rückgabewert hängen beim Klicken an oder fügen beim Ziehen an einer hervorgehobenen Lücke ein. Eine Zeile ziehen oder Hoch / Runter verwenden, um umzusortieren; Strg-Ziehen nimmt die folgenden Zeilen mit. Der Mülleimer entfernt eine Zeile. Typ und Nullbar dokumentieren die zulässigen Werte; Beschreibung erklärt jede Eingabe bzw. jedes Ergebnis. Lua kann mehrere geordnete Ergebnisse zurückgeben. Rückgabezeilen beschreiben diese Ergebnisse; ihr Verschieben schreibt keine return-Anweisungen um. Beim Umsortieren einer gespeicherten Funktion erscheint eine Warnung, da positionsabhängige Aufrufer eventuell angepasst werden müssen; RM schreibt Aufrufstellen nicht um.",
-- 183f4958 English: Enable Rotation Master recommendations, automatic rotation switching and bound
--     item-set updates. Disabling clears active advice and highlights and hides the preview. Apply
--     saves the change.
[3204] = "Aktiviert die Empfehlungen von Rotation Master, den automatischen Rotationswechsel und die Aktualisierung gebundener Gegenstandssets. Beim Deaktivieren werden aktive Empfehlungen und Hervorhebungen entfernt und die Vorschau ausgeblendet. „Übernehmen“ speichert die Änderung.",
-- c25b80af English: Set how often Rotation Master reevaluates the active rotation and independent
--     cooldowns, in seconds. A shorter interval updates advice more often and uses more processing
--     time. It does not cast spells, queue actions, or predict future combat.
[3205] = "Legt fest, wie oft Rotation Master die aktive Rotation und unabhängige Abklingzeiten neu auswertet, in Sekunden. Ein kürzeres Intervall aktualisiert die Empfehlungen häufiger und benötigt mehr Rechenzeit. Es wirkt keine Zauber, reiht keine Aktionen ein und sagt keinen künftigen Kampfverlauf voraus.",
-- 693c25ac English: Out of combat with no target and no focus, Rotation Master skips a polling tick
--     unless something it watches has changed: auras, cooldowns, health or power of you, your pet
--     or party, movement, casting, equipment, bags, form, pets or group. It still re-checks at
--     least this often, for time-based conditions (aura or cooldown remaining), distance, and
--     custom code. In combat, with any target or focus, or while configuration is open, every
--     polling tick is evaluated. Zero evaluates every polling tick.
[3206] = "Außerhalb des Kampfes ohne Ziel und ohne Fokus überspringt Rotation Master einen Abfragetakt, sofern sich nichts Beobachtetes geändert hat: Auren, Abklingzeiten, Gesundheit oder Ressource von Ihnen, Ihrem Begleiter oder Ihrer Gruppe, Bewegung, Zauberwirken, Ausrüstung, Taschen, Gestalt, Begleiter oder Gruppe. Mindestens in diesem Abstand wird trotzdem neu geprüft – für zeitbasierte Bedingungen (verbleibende Aura- oder Abklingzeit), Entfernung und benutzerdefinierten Code. Im Kampf, mit Ziel oder Fokus oder bei geöffneter Konfiguration wird jeder Abfragetakt ausgewertet. Null wertet jeden Abfragetakt aus.",
-- 658535de English: With automatic switching, Rotation Master checks this often, in and out of
--     combat, whether a different rotation's switch conditions now match, so conditions that change
--     on their own (nearby enemy count, threat, movement, health) take effect. Target, focus and
--     pet changes are checked straight away. Zero turns automatic switching off. Choosing a
--     rotation manually still overrides automatic switching until you choose Auto again.
[3207] = "Beim automatischen Wechsel prüft Rotation Master in diesem Abstand, im Kampf und außerhalb des Kampfes, ob jetzt die Umschaltbedingungen einer anderen Rotation zutreffen, damit sich selbst ändernde Bedingungen (Anzahl naher Feinde, Bedrohung, Bewegung, Gesundheit) wirksam werden. Ziel-, Fokus- und Begleiterwechsel werden sofort geprüft. Null schaltet den automatischen Wechsel ab. Eine manuell gewählte Rotation hat weiterhin Vorrang vor dem automatischen Wechsel, bis wieder „Auto“ gewählt wird.",
-- 93a9cab7 English: Hide the main rotation recommendation on action bars. Independent cooldown
--     highlights remain available. Enable Preview Spells if you want to see the main advice in a
--     separate window; with both displays off, the main recommendation has no visible icon.
[3208] = "Blendet die Hauptempfehlung der Rotation auf den Aktionsleisten aus. Hervorhebungen unabhängiger Abklingzeiten bleiben verfügbar. „Zaubervorschau“ aktivieren, um die Hauptempfehlung in einem eigenen Fenster zu sehen; sind beide Anzeigen aus, hat die Hauptempfehlung kein sichtbares Symbol.",
-- 186fa30f English: How often, in seconds, the rotation editor checks each card's condition for the
--     colored bar on the left of its condition field: green when it currently matches for you, red
--     when it does not, gray when it cannot be read at the moment (hover the condition for why and
--     when it was checked). Conditions are checked only while the editor is open; zero turns the
--     bars off. This is separate from the recommendation polling interval.
[3209] = "Wie oft der Rotationseditor, in Sekunden, die Bedingung jeder Karte für den farbigen Balken links neben ihrem Bedingungsfeld prüft: grün, wenn sie für Sie gerade zutrifft, rot, wenn nicht, grau, wenn sie im Moment nicht gelesen werden kann (fahren Sie mit der Maus über die Bedingung, um zu sehen, warum und wann sie geprüft wurde). Bedingungen werden nur geprüft, solange der Editor geöffnet ist; Null schaltet die Balken ab. Dies ist unabhängig vom Abfrageintervall der Empfehlungen.",
-- 8fc06fca English: Show the Rotation Master minimap icon. Left-click toggles the configuration
--     window. Right-click opens the quick menu for enabling recommendations and choosing a rotation
--     or automatic switching.
[3210] = "Zeigt das Minikartensymbol von Rotation Master. Linksklick öffnet oder schließt das Konfigurationsfenster. Rechtsklick öffnet das Schnellmenü, um Empfehlungen zu aktivieren und eine Rotation oder den automatischen Wechsel zu wählen.",
-- d11b9246 English: Choose Diagram or List as the starting rotation view. This profile preference
--     applies when opening a rotation; changing the view inside the editor does not change this
--     setting. Cooldowns always use a scrolling grid.
[3211] = "„Diagramm“ oder „Liste“ als Startansicht für Rotationen wählen. Diese Profileinstellung gilt beim Öffnen einer Rotation; ein Wechsel der Ansicht im Editor ändert diese Einstellung nicht. Abklingzeiten verwenden immer ein scrollbares Raster.",
-- a64c178e English: Choose how many seconds of previous spell casts to retain for history-based
--     conditions. Older casts are removed as recommendations update. A longer history retains more
--     records.
[3212] = "Wählt, wie viele Sekunden zurückliegender Zauber für verlaufsbasierte Bedingungen aufbewahrt werden. Ältere Zauber werden entfernt, während die Empfehlungen aktualisiert werden. Ein längerer Verlauf bewahrt mehr Einträge auf.",
-- 6572d0ab English: Choose how many seconds of combat events to retain for conditions such as
--     recent hits, parries and blocks. Older events are removed as recommendations update.
--     Availability depends on the client combat-data policy.
[3213] = "Wählt, wie viele Sekunden an Kampfereignissen für Bedingungen wie kürzliche Treffer, Parieren und Blocken aufbewahrt werden. Ältere Ereignisse werden entfernt, während die Empfehlungen aktualisiert werden. Die Verfügbarkeit hängt von der Kampfdaten-Richtlinie des Clients ab.",
-- 6c970b96 English: Choose how many seconds of observed damage and healing to retain for burn-rate
--     and time-to-die estimates. Recent observations receive more weight. A longer window uses more
--     records and smooths short changes; it cannot supply events the client does not expose.
[3214] = "Wählt, wie viele Sekunden an beobachtetem Schaden und beobachteter Heilung für Abbauraten- und Zeit-bis-zum-Tod-Schätzungen aufbewahrt werden. Neuere Beobachtungen werden stärker gewichtet. Ein längeres Fenster nutzt mehr Einträge und glättet kurze Änderungen; Ereignisse, die der Client nicht bereitstellt, kann es nicht liefern.",
-- 1826b95e English: Choose a whole number of upcoming recommendations, from zero (hidden) to five.
--     This is the only switch for the preview window: it is shown whenever this is above zero and
--     hidden at zero, and the window has no close button. The preview shows current priority
--     results, not a simulation of future cooldowns or combat. Icons start at 64 pixels; resizing
--     scales all icons while preserving their square shape and the window ratio.
[3215] = "Eine ganze Zahl kommender Empfehlungen wählen, von null (ausgeblendet) bis fünf. Dies ist der einzige Schalter für das Vorschaufenster: Es wird angezeigt, solange der Wert über null liegt, und bei null ausgeblendet; das Fenster hat keine Schließen-Schaltfläche. Die Vorschau zeigt die aktuellen Prioritätsergebnisse, keine Simulation künftiger Abklingzeiten oder Kämpfe. Symbole beginnen bei 64 Pixeln; eine Größenänderung skaliert alle Symbole und erhält ihre quadratische Form und das Fensterverhältnis.",
-- 9a03212a English: Adjust the preview background opacity without fading its icons. At zero only
--     the icons remain, the hidden background does not intercept blank-space clicks and the resize
--     grip is unavailable; an unlocked preview can still be dragged by its icons. Restore opacity
--     in General to resize it.
[3216] = "Passt die Deckkraft des Vorschauhintergrunds an, ohne die Symbole auszublenden. Bei null bleiben nur die Symbole übrig: Der unsichtbare Hintergrund fängt keine Klicks auf leere Flächen ab und der Größengriff ist nicht verfügbar; eine entsperrte Vorschau lässt sich weiterhin an ihren Symbolen ziehen. Die Deckkraft unter „Allgemein“ wiederherstellen, um die Größe zu ändern.",
-- 7884cae2 English: Unlocked, drag the preview by any icon or its background to move it, and resize
--     it from the grip that appears at its lower-right corner on hover. Locked, it cannot be moved
--     or resized and its background lets clicks through. Right-click an icon (or the background
--     while unlocked) for a menu to lock, unlock or open these settings. Locking and unlocking take
--     effect immediately and are saved without Apply. Other pending General edits remain unchanged.
[3217] = "Entsperrt lässt sich die Vorschau an einem beliebigen Symbol oder ihrem Hintergrund verschieben und über den Griff in der unteren rechten Ecke, der beim Überfahren erscheint, in der Größe ändern. Gesperrt kann sie weder verschoben noch in der Größe geändert werden, und ihr Hintergrund lässt Klicks durch. Ein Rechtsklick auf ein Symbol (oder entsperrt auf den Hintergrund) öffnet ein Menü zum Sperren, Entsperren oder Öffnen dieser Einstellungen. Sperren und Entsperren wirken sofort und werden ohne „Übernehmen“ gespeichert. Andere ausstehende Änderungen unter „Allgemein“ bleiben unverändert.",
-- 110dd6c2 English: Arrange preview icons horizontally (default) or vertically. Lock, Direction and
--     Reset share one row below the opacity slider. Changing direction keeps icons square and
--     adjusts the window ratio.
[3218] = "Ordnet die Vorschausymbole horizontal (Standard) oder vertikal an. „Sperren“, „Richtung“ und „Zurücksetzen“ teilen sich eine Zeile unter dem Deckkraft-Schieberegler. Beim Richtungswechsel bleiben die Symbole quadratisch und das Fensterverhältnis wird angepasst.",
-- 026621d4 English: Immediately return the preview window to the screen center and restore 64-pixel
--     icons without Apply. Other pending settings are preserved.
[3219] = "Setzt das Vorschaufenster sofort in die Bildschirmmitte zurück und stellt 64-Pixel-Symbole wieder her, ohne „Übernehmen“. Andere ausstehende Einstellungen bleiben erhalten.",
-- 46417b1b English: This icon previews the selected profile effect, color, size, anchor and
--     offsets. Previewing an effect does not save the draft or change the spell being recommended.
[3220] = "Dieses Symbol zeigt Effekt, Farbe, Größe, Anker und Versätze des ausgewählten Profils in der Vorschau. Die Vorschau eines Effekts speichert weder den Entwurf noch ändert sie den empfohlenen Zauber.",
-- 0e030acc English: Choose the highlight used for the main recommendation and as the default for
--     independent cooldowns. Manage available effects on the Effects page. A cooldown can override
--     these profile settings in its action details.
[3221] = "Wählt die Hervorhebung für die Hauptempfehlung und als Standard für unabhängige Abklingzeiten. Verfügbare Effekte werden auf der Seite „Effekte“ verwaltet. Eine Abklingzeit kann diese Profileinstellungen in ihren Aktionsdetails überschreiben.",
-- cf6729fa English: Scale the highlight relative to its action icon. A value of 1 uses the icon
--     size. Drag the slider or type its numeric value; the preview updates as you edit.
[3222] = "Skaliert die Hervorhebung relativ zu ihrem Aktionssymbol. Ein Wert von 1 entspricht der Symbolgröße. Den Schieberegler ziehen oder den Zahlenwert eingeben; die Vorschau aktualisiert sich beim Bearbeiten.",
-- 15842be8 English: Choose the highlight color and opacity. Click the color swatch to open the
--     picker, or enter R, G, B and A values between 0 and 1. Alpha controls opacity; individual
--     cooldowns may override this profile color.
[3223] = "Wählt Farbe und Deckkraft der Hervorhebung. Auf das Farbfeld klicken, um die Farbauswahl zu öffnen, oder R-, G-, B- und A-Werte zwischen 0 und 1 eingeben. Alpha steuert die Deckkraft; einzelne Abklingzeiten können diese Profilfarbe überschreiben.",
-- 27eafca9 English: Choose the point on the action icon where a texture highlight is anchored by
--     its center. Changing Anchor resets the offsets. The preview shows the resulting placement;
--     non-texture glows may use offsets without a texture anchor.
[3224] = "Wählt den Punkt am Aktionssymbol, an dem eine Textur-Hervorhebung mit ihrer Mitte verankert wird. Eine Änderung von „Anker“ setzt die Versätze zurück. Die Vorschau zeigt die resultierende Platzierung; Leuchteffekte ohne Textur können Versätze auch ohne Texturanker verwenden.",
-- 24139be0 English: Vertical offset in pixels. Use Up or Down on the position control, or edit V
--     directly. Hold Shift while using an arrow for ten pixels. Center resets both offsets and the
--     anchor to Center.
[3225] = "Vertikaler Versatz in Pixeln. „Nach oben“ oder „Nach unten“ an der Positionssteuerung verwenden oder V direkt bearbeiten. Mit gedrückter Umschalttaste bewegt ein Pfeil um zehn Pixel. „Mitte“ setzt beide Versätze zurück und den Anker auf „Mitte“.",
-- 64fcca62 English: Horizontal offset in pixels. Use Left or Right on the position control, or edit
--     H directly. Hold Shift while using an arrow for ten pixels. Non-texture glows interpret
--     offsets according to their effect shape.
[3226] = "Horizontaler Versatz in Pixeln. „Links“ oder „Rechts“ an der Positionssteuerung verwenden oder H direkt bearbeiten. Mit gedrückter Umschalttaste bewegt ein Pfeil um zehn Pixel. Leuchteffekte ohne Textur deuten Versätze je nach Form ihres Effekts.",
-- 199fbfc5 English: Choose the display name for your primary specialization. This changes its label
--     in Rotation Master, not your character talents or specialization.
[3227] = "Wählt den Anzeigenamen Ihrer primären Spezialisierung. Dies ändert nur die Bezeichnung in Rotation Master, nicht die Talente oder die Spezialisierung Ihres Charakters.",
-- 1647f2ad English: Choose the display name for your secondary specialization. This changes its
--     label in Rotation Master, not your character talents or specialization.
[3228] = "Wählt den Anzeigenamen Ihrer sekundären Spezialisierung. Dies ändert nur die Bezeichnung in Rotation Master, nicht die Talente oder die Spezialisierung Ihres Charakters.",
-- b49fc138 English: Choose the amount of Rotation Master chat output. Silent suppresses routine
--     output. Default reports normal changes such as rotation switching. Debug adds runtime
--     statistics and trigger information. Verbose includes detailed condition and highlight
--     activity and can produce substantial output.
[3229] = "Wählt den Umfang der Chatausgabe von Rotation Master. „Still“ unterdrückt Routineausgaben. „Standard“ meldet normale Änderungen wie Rotationswechsel. „Debug“ ergänzt Laufzeitstatistiken und Auslöserinformationen. „Ausführlich“ enthält detaillierte Bedingungs- und Hervorhebungsaktivität und kann sehr viel Ausgabe erzeugen.",
-- d0d316d9 English: Include component timings in the periodic Debug or Verbose profiling report.
--     Reports show measured runs, total, minimum, average and maximum in milliseconds. Timings
--     include child work; nested scopes overlap and must not be added together. The overall scope
--     starts after rotation preparation. This is elapsed timing, not the native addon CPU report.
[3230] = "Nimmt Komponentenzeiten in den regelmäßigen Profiling-Bericht der Stufen „Debug“ oder „Ausführlich“ auf. Berichte zeigen gemessene Durchläufe sowie Gesamt-, Minimal-, Durchschnitts- und Maximalzeit in Millisekunden. Zeiten schließen untergeordnete Arbeit ein; verschachtelte Bereiche überlappen sich und dürfen nicht addiert werden. Der Gesamtbereich beginnt nach der Rotationsvorbereitung. Gemessen wird die verstrichene Zeit, nicht der native Addon-CPU-Bericht.",
-- fd1963a1 English: Effects define how action-bar icons are highlighted. They are shared across
--     characters. General settings select the main recommendation effect and cooldown default;
--     individual cooldowns can choose another effect. Select an effect in the sidebar to inspect or
--     edit it.
[3231] = "Effekte legen fest, wie Symbole auf der Aktionsleiste hervorgehoben werden. Sie gelten für alle Charaktere gemeinsam. Die allgemeinen Einstellungen wählen den Effekt der Hauptempfehlung und den Standard für Abklingzeiten; einzelne Abklingzeiten können einen anderen Effekt wählen. Einen Effekt in der Seitenleiste auswählen, um ihn anzusehen oder zu bearbeiten.",
-- 40b0b9e0 English: Give the effect a name used by selectors in General and cooldown action
--     details. New drafts can change type and fields before being named, but Apply requires a
--     nonempty, unique name.
[3232] = "Gibt dem Effekt einen Namen, der in den Auswahllisten unter „Allgemein“ und in den Aktionsdetails von Abklingzeiten erscheint. Neue Entwürfe können Typ und Felder vor der Benennung ändern, „Übernehmen“ erfordert jedoch einen nicht leeren, eindeutigen Namen.",
-- 5a00db51 English: Choose the highlight implementation. Changing type stages the new fields and
--     resets its sequence because different sequence types store different values. Choosing the
--     current type preserves existing values. Apply saves the change; Discard restores the saved
--     effect.
[3233] = "Wählt die Art der Hervorhebung. Ein Typwechsel merkt die neuen Felder vor und setzt die Sequenz zurück, da verschiedene Sequenztypen unterschiedliche Werte speichern. Die Wahl des aktuellen Typs behält vorhandene Werte. „Übernehmen“ speichert die Änderung; „Verwerfen“ stellt den gespeicherten Effekt wieder her.",
-- c228a709 English: Texture: overlay a single image from game data or an installed addon. Its
--     color, magnification and position come from the profile or the individual cooldown.
[3234] = "Textur: legt ein einzelnes Bild aus den Spieldaten oder einem installierten Addon über das Symbol. Farbe, Vergrößerung und Position stammen aus dem Profil oder der einzelnen Abklingzeit.",
-- cd1a7948 English: Pixel: animate short lines around the action icon border. Lines, Frequency,
--     Length and Thickness control this library glow.
[3235] = "Pixel: animiert kurze Linien entlang des Rands des Aktionssymbols. „Linien“, „Frequenz“, „Länge“ und „Dicke“ steuern dieses Bibliotheksleuchten.",
-- 8f767bf7 English: Auto Cast: animate groups of glowing particles around the action icon.
--     Particles, Frequency and Scale control this library glow.
[3236] = "Autozauber: animiert Gruppen leuchtender Partikel um das Aktionssymbol. „Partikel“, „Frequenz“ und „Skalierung“ steuern dieses Bibliotheksleuchten.",
-- 0984e57a English: Glow: use the familiar Blizzard-style button glow. Frequency controls its
--     animation rate.
[3237] = "Leuchten: verwendet das vertraute Button-Leuchten im Blizzard-Stil. „Frequenz“ steuert die Animationsgeschwindigkeit.",
-- 4f13ce4d English: Dazzle: keep one texture and cycle through the sequence of colors. Each
--     sequence card contains one RGBA color.
[3238] = "Funkeln: behält eine Textur bei und durchläuft die Farbsequenz. Jede Sequenzkarte enthält eine RGBA-Farbe.",
-- 518c7a0b English: Animate: cycle through the sequence of texture images. Each card selects one
--     image and previews that selection.
[3239] = "Animieren: durchläuft die Sequenz der Texturbilder. Jede Karte wählt ein Bild und zeigt diese Auswahl in der Vorschau.",
-- 7db1adc9 English: Pulse: keep one texture and cycle through the sequence of magnifications. Each
--     card selects one scale relative to the action icon.
[3240] = "Pulsieren: behält eine Textur bei und durchläuft die Sequenz der Vergrößerungen. Jede Karte wählt eine Skalierung relativ zum Aktionssymbol.",
-- 04c25e44 English: Rotate: animate one texture through evenly spaced angles around a full circle.
--     Steps chooses the number of angles and Reverse changes their order.
[3241] = "Rotieren: dreht eine Textur über gleichmäßig verteilte Winkel eines vollen Kreises. „Schritte“ wählt die Anzahl der Winkel und „Umkehren“ ändert ihre Reihenfolge.",
-- e239b9d1 English: Custom: cycle through cards containing a texture, angle, magnification and
--     color. Each card supplies its own settings instead of relying on one shared texture.
[3242] = "Benutzerdefiniert: durchläuft Karten mit Textur, Winkel, Vergrößerung und Farbe. Jede Karte liefert eigene Einstellungen, statt sich auf eine gemeinsame Textur zu stützen.",
-- 1b35109f English: The image beside Name and Type previews the current draft with a white color
--     and standard size. Texture and sequence changes update the preview without saving. Actual
--     recommendations use their profile or cooldown color, size and offsets.
[3243] = "Das Bild neben „Name“ und „Typ“ zeigt den aktuellen Entwurf in Weiß und Standardgröße. Textur- und Sequenzänderungen aktualisieren die Vorschau, ohne zu speichern. Tatsächliche Empfehlungen verwenden Farbe, Größe und Versätze aus Profil oder Abklingzeit.",
-- 69030e6a English: For Texture, Dazzle, Pulse and Rotate, choose the image used throughout the
--     effect. The arrow beside an image field opens the bundled overlay catalog with previews.
--     Enter an available texture path or numeric file ID to use another image. Animate and Custom
--     choose images in their sequence cards using the same controls. Selections update the draft
--     and preview; Apply saves them.
[3244] = "Für Textur, Funkeln, Pulsieren und Rotieren das Bild wählen, das im gesamten Effekt verwendet wird. Der Pfeil neben einem Bildfeld öffnet den mitgelieferten Overlay-Katalog mit Vorschauen. Einen verfügbaren Texturpfad oder eine numerische Datei-ID eingeben, um ein anderes Bild zu verwenden. Animieren und Benutzerdefiniert wählen Bilder in ihren Sequenzkarten mit denselben Steuerelementen. Die Auswahl aktualisiert Entwurf und Vorschau; „Übernehmen“ speichert sie.",
-- 06895a3f English: Pixel effects: choose the number of animated lines around the button, from 1 to
--     20.
[3245] = "Pixel-Effekte: Anzahl der animierten Linien um den Button wählen, von 1 bis 20.",
-- 5a02f176 English: Pixel effects: signed cycles per second. A larger magnitude moves faster; a
--     negative value reverses direction. Zero uses the glow library default of one cycle every four
--     seconds.
[3246] = "Pixel-Effekte: Zyklen pro Sekunde mit Vorzeichen. Ein größerer Betrag bewegt sich schneller; ein negativer Wert kehrt die Richtung um. Null verwendet den Standard der Leuchtbibliothek von einem Zyklus alle vier Sekunden.",
-- 912f8432 English: Pixel effects: choose line length in pixels. The glow library limits it to the
--     smaller button dimension.
[3247] = "Pixel-Effekte: Linienlänge in Pixeln wählen. Die Leuchtbibliothek begrenzt sie auf die kleinere Abmessung des Buttons.",
-- 888c1858 English: Pixel effects: choose line thickness in pixels, from 1 to 5.
[3248] = "Pixel-Effekte: Liniendicke in Pixeln wählen, von 1 bis 5.",
-- f169cd48 English: Auto Cast effects: choose 1 to 4 particles in each of the glow library particle
--     groups.
[3249] = "Autozauber-Effekte: 1 bis 4 Partikel in jeder Partikelgruppe der Leuchtbibliothek wählen.",
-- 439eb6b4 English: Auto Cast effects: signed cycles per second. A larger magnitude moves faster; a
--     negative value reverses direction. Zero uses the glow library default of one cycle every
--     eight seconds.
[3250] = "Autozauber-Effekte: Zyklen pro Sekunde mit Vorzeichen. Ein größerer Betrag bewegt sich schneller; ein negativer Wert kehrt die Richtung um. Null verwendet den Standard der Leuchtbibliothek von einem Zyklus alle acht Sekunden.",
-- ee4e74b2 English: Auto Cast effects: scale the particles relative to the glow library default. A
--     value of 1 uses their normal size.
[3251] = "Autozauber-Effekte: skaliert die Partikel relativ zum Standard der Leuchtbibliothek. Ein Wert von 1 entspricht ihrer normalen Größe.",
-- 7a5e1fd3 English: Glow effects: adjust the library animation rate. Larger positive values animate
--     faster. Zero uses the library default rather than stopping the glow.
[3252] = "Leuchten-Effekte: passt die Animationsgeschwindigkeit der Bibliothek an. Größere positive Werte animieren schneller. Null verwendet den Bibliotheksstandard, statt das Leuchten anzuhalten.",
-- a09487cf English: Dazzle effects: seconds between color cards. A smaller positive interval
--     changes colors more often; the sequence repeats after the last color.
[3253] = "Funkeln-Effekte: Sekunden zwischen Farbkarten. Ein kleineres positives Intervall wechselt die Farben häufiger; nach der letzten Farbe wiederholt sich die Sequenz.",
-- 9e3ad582 English: Animate effects: seconds between texture cards. A smaller positive interval
--     changes images more often; the sequence repeats after the last image.
[3254] = "Animieren-Effekte: Sekunden zwischen Texturkarten. Ein kleineres positives Intervall wechselt die Bilder häufiger; nach dem letzten Bild wiederholt sich die Sequenz.",
-- 73861ddb English: Pulse effects: seconds between magnification cards. A smaller positive interval
--     changes size more often; the sequence repeats after the last size.
[3255] = "Pulsieren-Effekte: Sekunden zwischen Vergrößerungskarten. Ein kleineres positives Intervall ändert die Größe häufiger; nach der letzten Größe wiederholt sich die Sequenz.",
-- 6f691c60 English: Rotate effects: seconds between angle steps. A smaller positive interval
--     rotates faster. One full cycle uses this interval multiplied by Steps.
[3256] = "Rotieren-Effekte: Sekunden zwischen Winkelschritten. Ein kleineres positives Intervall dreht schneller. Ein voller Zyklus dauert dieses Intervall mal „Schritte“.",
-- 78b58b96 English: Rotate effects: choose 2 to 36 evenly spaced angles for a full turn. More steps
--     at the same Frequency interval make a longer complete cycle.
[3257] = "Rotieren-Effekte: 2 bis 36 gleichmäßig verteilte Winkel für eine volle Drehung wählen. Mehr Schritte bei gleichem Frequenzintervall ergeben einen längeren Gesamtzyklus.",
-- 98768f9e English: Rotate effects: reverse the order of angle steps. Changing this checkbox does
--     not alter the texture or number of steps.
[3258] = "Rotieren-Effekte: kehrt die Reihenfolge der Winkelschritte um. Dieses Kontrollkästchen ändert weder die Textur noch die Anzahl der Schritte.",
-- 0eaebb24 English: Custom effects: seconds between sequence cards. A smaller positive interval
--     changes settings more often; the sequence repeats after the last card.
[3259] = "Benutzerdefinierte Effekte: Sekunden zwischen Sequenzkarten. Ein kleineres positives Intervall wechselt die Einstellungen häufiger; nach der letzten Karte wiederholt sich die Sequenz.",
-- a85d837a English: Sequence cards play in order and repeat. Add step, on the Sequence header row,
--     appends a card; drag Add step into a gap to insert one there. Drag a card into an insertion
--     gap to reorder it; hold Ctrl when starting to carry it and all following cards. Up and Down
--     move one card and are disabled at their respective ends. The red trash removes a card from
--     the draft. Canceling a drag restores its original position.
[3260] = "Sequenzkarten werden der Reihe nach abgespielt und wiederholt. „Schritt hinzufügen“ in der Kopfzeile von „Sequenz“ hängt eine Karte an; „Schritt hinzufügen“ in eine Lücke ziehen, um dort eine einzufügen. Eine Karte in eine Einfügelücke ziehen, um sie neu anzuordnen; Strg beim Ziehbeginn gedrückt halten, um alle folgenden Karten mitzunehmen. „Nach oben“ und „Nach unten“ verschieben eine Karte und sind am jeweiligen Ende deaktiviert. Der rote Papierkorb entfernt eine Karte aus dem Entwurf. Ein abgebrochenes Ziehen stellt die ursprüngliche Position wieder her.",
-- d5a4691e English: Animate and Custom cards: choose a texture path or numeric file ID. The card
--     preview shows the selected image. Custom also keeps an independent angle, magnification and
--     color on that card.
[3261] = "Animieren- und Benutzerdefiniert-Karten: einen Texturpfad oder eine numerische Datei-ID wählen. Die Kartenvorschau zeigt das gewählte Bild. Benutzerdefiniert speichert auf dieser Karte zusätzlich eigenen Winkel, eigene Vergrößerung und Farbe.",
-- e9c4d7cb English: Custom cards: set the texture angle in degrees from 0 to 359. This is the angle
--     for this card, rather than a continuous rotation speed.
[3262] = "Benutzerdefiniert-Karten: Texturwinkel in Grad von 0 bis 359 festlegen. Dies ist der Winkel dieser Karte, keine fortlaufende Drehgeschwindigkeit.",
-- f9eb09ea English: Pulse and Custom cards: scale the texture relative to the action icon. A value
--     of 1 uses the icon size. Use the slider or edit its numeric value.
[3263] = "Pulsieren- und Benutzerdefiniert-Karten: skaliert die Textur relativ zum Aktionssymbol. Ein Wert von 1 entspricht der Symbolgröße. Den Schieberegler verwenden oder den Zahlenwert bearbeiten.",
-- a6ca83b6 English: Dazzle and Custom cards: choose an RGBA color. Click the swatch to open the
--     picker, or edit channels between 0 and 1. Alpha controls opacity.
[3264] = "Funkeln- und Benutzerdefiniert-Karten: eine RGBA-Farbe wählen. Auf das Farbfeld klicken, um die Farbauswahl zu öffnen, oder Kanäle zwischen 0 und 1 bearbeiten. Alpha steuert die Deckkraft.",
-- d838f5ee English: Edits and sequence changes remain in a draft. Apply saves; Discard restores the
--     saved effect. Cancel closes a new creation draft. View Changes compares saved and unsaved
--     values. New drafts require a unique name and valid fields before Apply. Leaving with edits
--     offers Apply, Discard or Cancel.
[3265] = "Bearbeitungen und Sequenzänderungen bleiben in einem Entwurf. „Übernehmen“ speichert; „Verwerfen“ stellt den gespeicherten Effekt wieder her. „Abbrechen“ schließt einen neuen Erstellungsentwurf. „Änderungen anzeigen“ vergleicht gespeicherte und ungespeicherte Werte. Neue Entwürfe benötigen vor „Übernehmen“ einen eindeutigen Namen und gültige Felder. Beim Verlassen mit Änderungen wird „Übernehmen“, „Verwerfen“ oder „Abbrechen“ angeboten.",
-- 781f5d06 English: The red trash at the upper right deletes the selected effect after a
--     permanent-deletion warning. Resolve pending edits first. Choose a replacement for any profile
--     or cooldown using that effect; deletion does not silently rewrite those references.
[3266] = "Der rote Papierkorb oben rechts löscht den ausgewählten Effekt nach einer Warnung vor dauerhafter Löschung. Ausstehende Bearbeitungen zuerst abschließen. Für jedes Profil und jede Abklingzeit, die diesen Effekt verwenden, einen Ersatz wählen; das Löschen schreibt diese Verweise nicht stillschweigend um.",
-- a8f923ca English: New, Duplicate, Import/Export and Compare are below the sidebar. Duplicate
--     copies the selected effect into a draft. Transfers show the original name and let you create
--     a renamed copy or replace the selection when allowed. Compare inspects differences without
--     saving them.
[3267] = "„Neu“, „Duplizieren“, „Import/Export“ und „Vergleichen“ befinden sich unter der Seitenleiste. „Duplizieren“ kopiert den ausgewählten Effekt in einen Entwurf. Übertragungen zeigen den ursprünglichen Namen und erlauben eine umbenannte Kopie oder, falls zulässig, das Ersetzen der Auswahl. „Vergleichen“ prüft Unterschiede, ohne sie zu speichern.",
-- fe52fcf9 English: Selecting a sidebar row only inspects that profile. Activate profile switches
--     the live profile immediately, including its rotations and settings. The active profile shows
--     Active profile instead. This operation does not wait for page Apply.
[3268] = "Das Auswählen einer Zeile in der Seitenleiste zeigt dieses Profil nur an. „Profil aktivieren“ wechselt das aktive Profil sofort, einschließlich seiner Rotationen und Einstellungen. Beim aktiven Profil steht stattdessen „Aktives Profil“. Dieser Vorgang wartet nicht auf „Übernehmen“ der Seite.",
-- 605ecea0 English: Choose a source to replace the active profile after confirmation. This copies
--     settings and rotations into the active profile, even when the sidebar is inspecting a
--     different profile. It does not switch to the source or rename the active profile. Cancel at
--     the confirmation preserves the current profile.
[3269] = "Eine Quelle wählen, die nach Bestätigung das aktive Profil ersetzt. Dies kopiert Einstellungen und Rotationen in das aktive Profil, auch wenn die Seitenleiste gerade ein anderes Profil anzeigt. Es wird weder zur Quelle gewechselt noch das aktive Profil umbenannt. „Abbrechen“ bei der Bestätigung behält das aktuelle Profil.",
-- d403202f English: Reset current profile replaces the active profile with its defaults after
--     confirmation. Custom rotations and settings in it are replaced. The control is disabled while
--     inspecting another profile. Reset is immediate after confirmation; there is no later page
--     Apply to undo it.
[3270] = "„Aktuelles Profil zurücksetzen“ ersetzt das aktive Profil nach Bestätigung durch seine Standardwerte. Benutzerdefinierte Rotationen und Einstellungen darin werden ersetzt. Die Schaltfläche ist deaktiviert, solange ein anderes Profil angezeigt wird. Das Zurücksetzen erfolgt sofort nach der Bestätigung; es gibt kein späteres „Übernehmen“ der Seite, mit dem es sich rückgängig machen ließe.",
-- 071e02f8 English: The red trash can permanently removes the selected inactive profile after
--     confirmation. The active profile and Default cannot be deleted here. Selecting another
--     profile does not delete or activate it.
[3271] = "Der rote Papierkorb entfernt das ausgewählte inaktive Profil nach Bestätigung dauerhaft. Das aktive Profil und „Default“ können hier nicht gelöscht werden. Das Auswählen eines anderen Profils löscht oder aktiviert dieses nicht.",
-- e0223ba4 English: New and Duplicate open a named draft. Use a nonblank, unused name of at most 50
--     characters. Apply creates the profile; Cancel abandons creation. Creating a profile leaves
--     the previously active profile active, so use Activate profile when you want to switch to the
--     new copy.
[3272] = "„Neu“ und „Duplizieren“ öffnen einen benannten Entwurf. Einen nicht leeren, unbenutzten Namen mit höchstens 50 Zeichen verwenden. „Übernehmen“ erstellt das Profil; „Abbrechen“ verwirft die Erstellung. Nach dem Erstellen bleibt das bisher aktive Profil aktiv; mit „Profil aktivieren“ zur neuen Kopie wechseln.",
-- c85ff72a English: The buttons below the list create a new profile, duplicate the selected
--     profile, transfer profiles or compare saved settings. Search narrows the list without
--     activating a profile. Import/Export shows the original name and lets you replace the
--     selection or create a renamed copy. Importing a new profile opens a creation draft; Apply
--     saves it. Replacing a selected profile happens when you confirm the import, and replacing the
--     active profile updates its runtime settings. Compare does not apply changes.
[3273] = "Mit den Schaltflächen unter der Liste wird ein neues Profil erstellt, das ausgewählte Profil dupliziert, Profile übertragen oder gespeicherte Einstellungen verglichen. Die Suche schränkt die Liste ein, ohne ein Profil zu aktivieren. „Import/Export“ zeigt den ursprünglichen Namen und erlaubt, die Auswahl zu ersetzen oder eine umbenannte Kopie zu erstellen. Der Import eines neuen Profils öffnet einen Erstellungsentwurf; „Übernehmen“ speichert ihn. Ein ausgewähltes Profil wird ersetzt, sobald der Import bestätigt wird, und das Ersetzen des aktiven Profils aktualisiert seine Laufzeiteinstellungen. „Vergleichen“ übernimmt keine Änderungen.",
-- d58adae2 English: Status pills show Not loaded, Supported, Disabled, Enabled or Selected. Click
--     Enabled to Select or Disable. Disabling Selected chooses the sole enabled available editor,
--     offers a choice when several exist, or leaves none selected. Enabling an editor when none is
--     selected selects it automatically. Native is always available; its Syntax highlighting option
--     is independent of editor selection. With no enabled editor, emergency plain text remains
--     usable. Apply saves preferences for the next source-editor opening; Discard keeps saved
--     settings. An open editor keeps its current provider.
[3274] = "Statusanzeigen zeigen „Nicht geladen“, „Unterstützt“, „Deaktiviert“, „Aktiviert“ oder „Ausgewählt“. Auf „Aktiviert“ klicken, um „Auswählen“ oder „Deaktivieren“ zu wählen. Das Deaktivieren von „Ausgewählt“ wählt den einzigen aktivierten verfügbaren Editor, bietet bei mehreren eine Auswahl an oder lässt keinen ausgewählt. Wird ein Editor aktiviert, während keiner ausgewählt ist, wird er automatisch ausgewählt. „Nativ“ ist immer verfügbar; seine Option „Syntaxhervorhebung“ ist unabhängig von der Editorauswahl. Ohne aktivierten Editor bleibt der Notfall-Klartext nutzbar. „Übernehmen“ speichert die Einstellungen für das nächste Öffnen eines Quelltext-Editors; „Verwerfen“ behält die gespeicherten Einstellungen. Ein geöffneter Editor behält seinen aktuellen Anbieter.",
-- 3bdeb012 English: Show line numbers controls the gutter in every condition and function code
--     editor. It defaults to enabled. Apply saves the preference and updates open code panes;
--     Discard keeps the saved setting. It does not change the Lua source or its line breaks.
[3275] = "„Zeilennummern anzeigen“ steuert die Randspalte in jedem Code-Editor für Bedingungen und Funktionen. Standardmäßig aktiviert. „Übernehmen“ speichert die Einstellung und aktualisiert geöffnete Code-Bereiche; „Verwerfen“ behält die gespeicherte Einstellung. Der Lua-Quelltext und seine Zeilenumbrüche werden nicht geändert.",
-- e69d5940 English: Addon names open copyable official release and source links across available
--     providers. Edition filtering follows declared support for the matching addon identity;
--     unknown compatibility remains visible. An older release date alone does not prove
--     incompatibility. Listed game-edition support describes publisher release evidence, not
--     certification of the integration on your client. Some integrations have only historical or
--     unverified releases. Not loaded means unavailable to RM; Supported identifies an available
--     integration without an enable switch. Bundled libraries are excluded. Rotation Master does
--     not install or enable other addons.
[3276] = "Addon-Namen öffnen kopierbare offizielle Release- und Quelltext-Links der verfügbaren Anbieter. Die Filterung nach Edition folgt der erklärten Unterstützung für die passende Addon-Identität; unbekannte Kompatibilität bleibt sichtbar. Ein älteres Veröffentlichungsdatum allein beweist keine Inkompatibilität. Die angegebene Unterstützung von Spieleditionen beschreibt Veröffentlichungsnachweise des Herausgebers, keine Zertifizierung der Integration auf Ihrem Client. Für manche Integrationen gibt es nur historische oder ungeprüfte Releases. „Nicht geladen“ bedeutet für RM nicht verfügbar; „Unterstützt“ kennzeichnet eine verfügbare Integration ohne Aktivierungsschalter. Mitgelieferte Bibliotheken sind ausgenommen. Rotation Master installiert oder aktiviert keine anderen Addons.",
-- 6c182d42 English: Apply / Discard
-- Context: Help topic title for the buttons that save or abandon edits in an item list dialog and
--     the window.
[3277] = "Übernehmen / Verwerfen",
-- d04a65ba English: Edits stay in a draft until Apply. Discard abandons pending changes. Leaving
--     with changes offers Apply, Discard or Cancel; Cancel keeps the page and draft open. Effect
--     previews do not save changes. Action-bar binding operations are explicit and immediate.
[3278] = "Bearbeitungen bleiben bis „Übernehmen“ in einem Entwurf. „Verwerfen“ verwirft ausstehende Änderungen. Beim Verlassen mit Änderungen wird „Übernehmen“, „Verwerfen“ oder „Abbrechen“ angeboten; „Abbrechen“ lässt Seite und Entwurf geöffnet. Effektvorschauen speichern keine Änderungen. Bindungsvorgänge auf Aktionsleisten erfolgen ausdrücklich und sofort.",
-- 2be8c485 English: Diagram / List changes only the rotation view; General settings choose the
--     default. Diagram has floating minus, percentage and plus controls at the bottom right. Scroll
--     to zoom from 25% to 200%; click the percentage or middle-click to reset to 100%. Drag empty
--     diagram space to pan. List uses normal scrollbars with touching cards and boxed branch arms,
--     False before True. Cooldowns use a separate scrolling grid. Dragging cards reorders them in
--     every view. Valid rotation bodies can contain up to 2,000 total steps; large workspaces reuse
--     nearby card controls as you navigate. Folded branches intentionally hide their children.
[3279] = "„Diagramm / Liste“ ändert nur die Rotationsansicht; den Standard wählen die allgemeinen Einstellungen. Das Diagramm hat unten rechts schwebende Minus-, Prozent- und Plus-Steuerelemente. Mit dem Mausrad von 25 % bis 200 % zoomen; auf die Prozentangabe klicken oder mittelklicken, um auf 100 % zurückzusetzen. Leere Diagrammfläche ziehen, um die Ansicht zu verschieben. Die Liste verwendet normale Bildlaufleisten mit aneinanderliegenden Karten und umrahmten Verzweigungsarmen, False vor True. Abklingzeiten verwenden ein eigenes scrollbares Raster. Das Ziehen von Karten ordnet sie in jeder Ansicht neu an. Gültige Rotationsrümpfe können insgesamt bis zu 2.000 Schritte enthalten; große Arbeitsbereiche verwenden beim Navigieren nahe Kartensteuerelemente wieder. Eingeklappte Verzweigungen blenden ihre Unterelemente absichtlich aus.",
-- 76bac84a English: New / Duplicate / Import / Compare
[3280] = "Neu / Duplizieren / Import / Vergleichen",
-- c4875790 English: Choose a category and search for a condition. Hidden removes it from pickers
--     without deleting its definition. Switch Condition controls its availability for automatic
--     rotation switching. Move To stages a category destination; its Apply button confirms the
--     move. The assigned category opens category management. Sidebar arrows and dragging order
--     entries. Page Apply saves the draft; Discard abandons edits to a saved entry. Custom
--     conditions can be edited, duplicated or deleted.
[3281] = "Eine Kategorie wählen und nach einer Bedingung suchen. „Ausgeblendet“ entfernt sie aus Auswahllisten, ohne ihre Definition zu löschen. „Umschaltbedingung“ steuert ihre Verfügbarkeit für den automatischen Rotationswechsel. „Verschieben nach“ merkt eine Zielkategorie vor; die zugehörige Schaltfläche „Übernehmen“ bestätigt das Verschieben. Die zugewiesene Kategorie öffnet die Kategorieverwaltung. Pfeile in der Seitenleiste und Ziehen ordnen Einträge an. „Übernehmen“ der Seite speichert den Entwurf; „Verwerfen“ verwirft Bearbeitungen an einem gespeicherten Eintrag. Benutzerdefinierte Bedingungen können bearbeitet, dupliziert oder gelöscht werden.",
-- be63470b English: Select an effect to edit its name, type and type-specific settings. The icon
--     previews it live. Sequence sections edit animation, color, pulse or custom frames in order.
--     Duplicate creates an independent effect. Drag a sequence card surface to reorder it; fields
--     remain editable. New effects can be configured before naming. Apply saves the draft; Discard
--     abandons edits to a saved entry. Import stages a validated replacement.
[3282] = "Einen Effekt auswählen, um Name, Typ und typspezifische Einstellungen zu bearbeiten. Das Symbol zeigt ihn live in der Vorschau. Sequenzabschnitte bearbeiten Animations-, Farb-, Puls- oder benutzerdefinierte Einzelbilder der Reihe nach. „Duplizieren“ erstellt einen unabhängigen Effekt. Die Fläche einer Sequenzkarte ziehen, um sie neu anzuordnen; Felder bleiben bearbeitbar. Neue Effekte können vor der Benennung konfiguriert werden. „Übernehmen“ speichert den Entwurf; „Verwerfen“ verwirft Bearbeitungen an einem gespeicherten Eintrag. Der Import merkt einen geprüften Ersatz vor.",
-- e7df5868 English: Choose an item set and edit its priority list. Global shares the set across
--     profiles. Move arrows change item priority. Bind item set picks up an available item for
--     placement on an action bar; The binding pill removes matching bound bar actions when
--     unbinding, outside combat. Reset restores a packaged set. Search or drag items into reference
--     fields. Apply saves settings; Discard abandons edits to a saved entry. Binding changes are
--     explicit action-bar operations.
[3283] = "Ein Gegenstandsset wählen und seine Prioritätsliste bearbeiten. „Global“ teilt das Set über alle Profile. Pfeile ändern die Priorität eines Gegenstands. „Gegenstandsset binden“ nimmt einen verfügbaren Gegenstand auf, um ihn auf einer Aktionsleiste abzulegen; die Bindungsanzeige entfernt beim Lösen außerhalb des Kampfes passende gebundene Leistenaktionen. „Zurücksetzen“ stellt ein mitgeliefertes Set wieder her. Gegenstände suchen oder in Verweisfelder ziehen. „Übernehmen“ speichert Einstellungen; „Verwerfen“ verwirft Bearbeitungen an einem gespeicherten Eintrag. Bindungsänderungen sind ausdrückliche Vorgänge auf der Aktionsleiste.",
-- 27a02657 English: Press Enter or leave a text field to stage its value; Apply saves the draft.
--     Invalid text stays red and must be corrected before Apply; Discard can abandon it. Searchable
--     selectors open on click and filter as you type. Section headings collapse or expand their
--     contents.
[3284] = "Die Eingabetaste drücken oder ein Textfeld verlassen, um seinen Wert vorzumerken; „Übernehmen“ speichert den Entwurf. Ungültiger Text bleibt rot und muss vor „Übernehmen“ korrigiert werden; mit „Verwerfen“ lässt er sich verwerfen. Durchsuchbare Auswahllisten öffnen sich per Klick und filtern während der Eingabe. Abschnittsüberschriften klappen ihren Inhalt ein oder aus.",
-- 53a70ff7 English: Editing this list
-- Context: Help topic title at the top of the item list dialog help.
[3285] = "Diese Liste wird bearbeitet",
-- d71ea291 English: This window edits only the item list you opened. Search or drag items into the
--     fields, then arrange preferred items first. A named item set is shared by its other users; a
--     custom list belongs to the calling condition or action draft. Applying this list does not
--     apply the parent editor.
[3286] = "Dieses Fenster bearbeitet nur die geöffnete Gegenstandsliste. Gegenstände suchen oder in die Felder ziehen und bevorzugte Gegenstände an den Anfang stellen. Ein benanntes Gegenstandsset wird mit seinen anderen Nutzern geteilt; eine benutzerdefinierte Liste gehört zur aufrufenden Bedingung oder zum Aktionsentwurf. Das Übernehmen dieser Liste übernimmt nicht den übergeordneten Editor.",
-- 05cdc879 English: Use a row's red trash can to remove that entry from the draft list. This does
--     not delete a named item set or remove an item from your inventory. The removal takes effect
--     when you Apply this list.
[3287] = "Der rote Papierkorb einer Zeile entfernt diesen Eintrag aus der Entwurfsliste. Dies löscht weder ein benanntes Gegenstandsset noch entfernt es einen Gegenstand aus Ihrem Inventar. Das Entfernen wird wirksam, wenn diese Liste übernommen wird.",
-- 3cedce54 English: Apply validates every entry and writes the edited list back to its original
--     owner. Discard closes without changing it. Closing with pending edits offers Apply, Discard
--     or Cancel; Cancel keeps this window open. View Changes compares the original list with this
--     draft. If the original list changed elsewhere, close and reopen it before applying.
[3288] = "„Übernehmen“ prüft jeden Eintrag und schreibt die bearbeitete Liste an ihren ursprünglichen Besitzer zurück. „Verwerfen“ schließt, ohne sie zu ändern. Beim Schließen mit ausstehenden Bearbeitungen wird „Übernehmen“, „Verwerfen“ oder „Abbrechen“ angeboten; „Abbrechen“ lässt dieses Fenster geöffnet. „Änderungen anzeigen“ vergleicht die ursprüngliche Liste mit diesem Entwurf. Wurde die ursprüngliche Liste an anderer Stelle geändert, vor dem Übernehmen schließen und erneut öffnen.",
-- 54637cac English: Proc Glow: use the animated actionbar proc border from LibCustomGlow. Rotation
--     Master checks the required game artwork and animation support before using it. Unsupported
--     clients use Pixel glow instead; the definition remains portable. Color and offsets come from
--     the profile or the cooldown.
[3289] = "Proc-Leuchten: verwendet den animierten Proc-Rahmen der Aktionsleiste aus LibCustomGlow. Rotation Master prüft vor der Verwendung, ob die benötigte Spielgrafik und Animationsunterstützung vorhanden sind. Nicht unterstützte Clients verwenden stattdessen Pixel-Leuchten; die Definition bleibt übertragbar. Farbe und Versätze stammen aus dem Profil oder der Abklingzeit.",
-- 265e2457 English: Time in seconds for one repeating proc-border animation, from 0.1 to 5. Use the
--     slider or enter an exact value in its number field. Changing the value updates the preview.
[3290] = "Dauer in Sekunden für einen Durchlauf der sich wiederholenden Proc-Rahmen-Animation, von 0,1 bis 5. Den Schieberegler verwenden oder einen genauen Wert in sein Zahlenfeld eingeben. Eine Änderung des Werts aktualisiert die Vorschau.",
-- 50bd053e English: Play the opening burst when this highlight first appears, then repeat its
--     border animation. Off by default. Refreshing an already visible Proc Glow does not restart
--     the burst.
[3291] = "Spielt beim ersten Erscheinen dieser Hervorhebung den Startblitz ab und wiederholt dann die Rahmenanimation. Standardmäßig aus. Das Auffrischen eines bereits sichtbaren Proc-Leuchtens startet den Startblitz nicht neu.",
-- a0515628 English: Rotations belong to the active settings profile. New copies use Class, shared
--     by your characters of that class; Metadata can change this to This character. Built In
--     rotations show only for their declared class or universal use. Equal identifiers in different
--     owners remain separate entries.
[3292] = "Rotationen gehören zum aktiven Einstellungsprofil. Neue Kopien verwenden „Klasse“ und werden von Ihren Charakteren dieser Klasse gemeinsam genutzt; unter „Metadaten“ lässt sich dies auf „Dieser Charakter“ ändern. Integrierte Rotationen erscheinen nur für ihre angegebene Klasse oder bei universeller Verwendung. Gleiche Kennungen bei verschiedenen Besitzern bleiben getrennte Einträge.",
-- 774a185e English: Older rotations without a recorded owner stay in an archive. Recover unassigned
--     rotations opens the current profile and character archives for inspection or copying. Choose
--     Class or This character to adopt one. Adoption preserves its identifier and evidence, refuses
--     an existing destination, and leaves incomplete records unavailable until repaired.
[3293] = "Ältere Rotationen ohne erfassten Besitzer bleiben in einem Archiv. „Nicht zugeordnete Rotationen wiederherstellen“ öffnet die Archive des aktuellen Profils und Charakters zum Ansehen oder Kopieren. „Klasse“ oder „Dieser Charakter“ wählen, um eine davon zuzuordnen. Die Zuordnung behält Kennung und Nachweise bei, verweigert ein bereits vorhandenes Ziel und lässt unvollständige Einträge bis zur Reparatur nicht verfügbar.",
-- 4886d663 English: Enable Questie integration
-- Context: Help topic title in Integrations help for the checkbox that turns on the Questie
--     integration.
[3294] = "Questie-Integration aktivieren",
-- 3a9724aa English: Review supported addons, detected versions and status by integration type.
--     Expand or collapse each integration group. Click an addon name to choose a copyable release
--     or source link. Configure editor and optional provider preferences here; Apply saves
--     preferences for this profile and Discard keeps saved settings.
[3295] = "Unterstützte Addons, erkannte Versionen und Status nach Integrationsart prüfen. Jede Integrationsgruppe lässt sich ein- oder ausklappen. Auf einen Addon-Namen klicken, um einen kopierbaren Release- oder Quelltext-Link zu wählen. Hier werden Editor- und optionale Anbietereinstellungen festgelegt; „Übernehmen“ speichert die Einstellungen für dieses Profil und „Verwerfen“ behält die gespeicherten.",
-- 25f09788 English: Opt in to Questie callbacks for this profile, then Apply. Discard does not
--     change the saved connection. Readiness, API compatibility, source-tested version and native
--     acceptance are reported separately. The adapter retains recent update receipts only; they do
--     not prove quest progress or completion and do not select rotations. No background polling is
--     used.
[3296] = "Questie-Callbacks für dieses Profil aktivieren und dann „Übernehmen“ wählen. „Verwerfen“ ändert die gespeicherte Verbindung nicht. Bereitschaft, API-Kompatibilität, am Quelltext getestete Version und native Abnahme werden getrennt gemeldet. Der Adapter bewahrt nur kürzliche Aktualisierungsbelege auf; diese belegen weder Questfortschritt noch Questabschluss und wählen keine Rotationen aus. Es findet keine Abfrage im Hintergrund statt.",
-- 3877e4d7 English: Enable DBM or BigWigs to feed the Boss Mod conditions (encounter, stage and
--     ability timers), then Apply. Only one boss mod can be enabled; enabling one disables the
--     other. RM listens to the boss mod's own callbacks and never polls it or changes its settings.
--     With none enabled, or the enabled addon not loaded, Boss Mod conditions are unavailable.
--     Supported on Classic Era, TBC and Classic progression clients.
[3297] = "DBM oder BigWigs aktivieren, um die Boss-Mod-Bedingungen (Begegnung, Phase und Fähigkeitentimer) zu versorgen, dann „Übernehmen“. Es kann nur ein Boss-Mod aktiviert sein; das Aktivieren des einen deaktiviert den anderen. RM hört auf die eigenen Callbacks des Boss-Mods, fragt ihn nie ab und ändert nie seine Einstellungen. Ist keiner aktiviert oder das aktivierte Addon nicht geladen, sind die Boss-Mod-Bedingungen nicht verfügbar. Unterstützt auf Clients von Classic Era, TBC und Classic-Progression.",
-- c9949fc6 English: Rotation Master publishes a LibDataBroker data source with the active rotation,
--     a tooltip and click menus. Titan Panel and other LibDataBroker displays show it without
--     further setup: in Titan, add Rotation Master from the plugin menu. Panel absence has no
--     effect on rotation selection.
[3298] = "Rotation Master stellt eine LibDataBroker-Datenquelle mit der aktiven Rotation, einem Tooltip und Klickmenüs bereit. Titan Panel und andere LibDataBroker-Anzeigen zeigen sie ohne weitere Einrichtung an: In Titan Rotation Master über das Plugin-Menü hinzufügen. Das Fehlen einer Leiste wirkt sich nicht auf die Rotationsauswahl aus.",
-- 59df493c English: Record spell cast receipts for thirty seconds without changing settings or
--     gameplay polling. While it runs this button reads Stop cast capture and ends the capture
--     early, keeping what was recorded.
[3299] = "Zeichnet dreißig Sekunden lang Belege gewirkter Zauber auf, ohne Einstellungen oder die Abfrage im Spiel zu ändern. Während der Aufzeichnung heißt diese Schaltfläche „Zaubererfassung beenden“ und beendet die Erfassung vorzeitig; das bisher Aufgezeichnete bleibt erhalten.",
-- 0ffbf212 English: Open the copyable cast receipt report. It stays disabled until a cast capture
--     has produced a report and while a capture is running.
[3300] = "Öffnet den kopierbaren Bericht der Zauberbelege. Die Schaltfläche bleibt deaktiviert, bis eine Zaubererfassung einen Bericht erzeugt hat, und solange eine Erfassung läuft.",
-- 472590ae English: Provider
-- Context: Column heading in the addon download links dialog: the website that hosts the download
--     (e.g. CurseForge).
[3301] = "Anbieter",
-- e7a241de English: URL
-- Context: Column heading in the addon download links dialog: the web address of the download page.
[3302] = "URL",
-- 8ea4edb6 English: Select URL for copying (Ctrl+C)
[3303] = "URL zum Kopieren markieren (Strg+C)",
-- 42592899 English: Syntax highlighting applies only to the Native Lua editor. Apply saves this
--     preference for the next source-editor opening; it does not switch a selected external editor.
--     Show line numbers under the editor heading applies to every provider.
[3304] = "Syntaxhervorhebung gilt nur für den nativen Lua-Editor. „Übernehmen“ speichert diese Einstellung für das nächste Öffnen eines Quelltext-Editors; ein ausgewählter externer Editor wird dadurch nicht gewechselt. „Zeilennummern anzeigen“ unter der Editor-Überschrift gilt für jeden Anbieter.",
-- eb084da9 English: Enable separately installed Masque here and Apply. General > Preview then
--     provides a Skin dropdown that updates the preview immediately. Masque owns the skin
--     selection; /masque opens its other settings. The preview window keeps its native appearance.
--     Missing or incompatible APIs and provider errors retain the native preview.
[3305] = "Separat installiertes Masque hier aktivieren und „Übernehmen“ wählen. Unter Allgemein > Vorschau steht dann ein Auswahlmenü „Skin“ bereit, das die Vorschau sofort aktualisiert. Masque verwaltet die Skin-Auswahl; /masque öffnet seine weiteren Einstellungen. Das Vorschaufenster behält sein natives Erscheinungsbild. Bei fehlenden oder inkompatiblen APIs und Anbieterfehlern bleibt die native Vorschau erhalten.",
-- 34199d23 English: Enable Masque in Integrations to choose a skin. Skin changes update the open
--     preview immediately and are saved by Masque, independently of Apply or Discard. Without
--     enabled Masque support, the preview uses Blizzard Classic. Preview toggles sample icons
--     whether Masque is enabled or not.
[3306] = "Masque unter „Integrationen“ aktivieren, um einen Skin zu wählen. Skin-Änderungen aktualisieren die geöffnete Vorschau sofort und werden von Masque gespeichert, unabhängig von „Übernehmen“ oder „Verwerfen“. Ohne aktivierte Masque-Unterstützung verwendet die Vorschau Blizzard Classic. „Vorschau“ schaltet Beispielsymbole um, ob Masque aktiviert ist oder nicht.",
-- 5b167013 English: Click Preview to toggle temporary sample icons when no real recommendations are
--     available. Real recommendations replace the samples. This does not change Preview Spells,
--     cast spells, or save the sample state.
[3307] = "Auf „Vorschau“ klicken, um vorübergehende Beispielsymbole ein- oder auszuschalten, wenn keine echten Empfehlungen verfügbar sind. Echte Empfehlungen ersetzen die Beispiele. Dies ändert weder „Zaubervorschau“ noch wirkt es Zauber oder speichert den Beispielzustand.",
-- 04025773 English: Optional conditions use the Announcement condition list and All, Any and Not
--     groups. For spell, pet and item announcements, they run when the configured action and event
--     match. For Via Script/Macro, they run when you invoke the saved identifier. Each output card
--     checks its own conditions. Only a matching result allows that output; unavailable data skips
--     that card while later cards remain independent. In Group can check the Spell recipient
--     recorded for this cast, including click casting, without using your selected target. Choose
--     Announcement target to check the spell recipient for automatic entries, or the supplied unit
--     for Via Script/Macro; Whisper uses that same supplied unit. Automatic entries pass the
--     recorded recipient name to native unit queries. A missing or unresolvable recipient skips its
--     required condition; an unrelated selected target is never substituted. Missing or ambiguous
--     required recipients do not match. Apply in the condition editor updates the announcement
--     draft; Apply on Announces saves it. Cancel or Discard abandons draft changes.
[3308] = "Optionale Bedingungen verwenden die Bedingungsliste für Ankündigungen sowie die Gruppen „Alle“, „Beliebig“ und „Nicht“. Bei Zauber-, Begleiter- und Gegenstandsankündigungen werden sie ausgewertet, wenn die konfigurierte Aktion und das Ereignis passen. Bei „Per Skript/Makro“ werden sie ausgewertet, wenn die gespeicherte Kennung aufgerufen wird. Jede Ausgabekarte prüft ihre eigenen Bedingungen. Nur ein zutreffendes Ergebnis erlaubt diese Ausgabe; nicht verfügbare Daten überspringen diese Karte, während spätere Karten unabhängig bleiben. „In Gruppe“ kann den für diesen Zauber erfassten Zauberempfänger prüfen, auch beim Klick-Zaubern, ohne Ihr ausgewähltes Ziel zu verwenden. „Ankündigungsziel“ wählen, um bei automatischen Einträgen den Zauberempfänger oder bei „Per Skript/Makro“ die übergebene Einheit zu prüfen; „Flüstern“ verwendet dieselbe übergebene Einheit. Automatische Einträge übergeben den erfassten Empfängernamen an native Einheitenabfragen. Ein fehlender oder nicht auflösbarer Empfänger überspringt seine erforderliche Bedingung; ein unbeteiligtes ausgewähltes Ziel wird nie ersatzweise verwendet. Fehlende oder mehrdeutige erforderliche Empfänger treffen nicht zu. „Übernehmen“ im Bedingungseditor aktualisiert den Ankündigungsentwurf; „Übernehmen“ unter „Ankündigungen“ speichert ihn. „Abbrechen“ oder „Verwerfen“ verwirft Entwurfsänderungen.",
-- 6c64ce13 English: Choose the unit whose membership in your party or raid is checked. Player keeps
--     the original player group-status behavior. Spell recipient uses only the current announcement
--     event context; without that readable context the result is unavailable. It never substitutes
--     your selected target or a previous cast.
[3309] = "Die Einheit wählen, deren Mitgliedschaft in Ihrer Gruppe oder Ihrem Schlachtzug geprüft wird. „Spieler“ behält das ursprüngliche Verhalten für den Gruppenstatus des Spielers bei. „Zauberempfänger“ verwendet nur den Kontext des aktuellen Ankündigungsereignisses; ohne lesbaren Kontext ist das Ergebnis nicht verfügbar. Ihr ausgewähltes Ziel oder ein früherer Zauber wird nie ersatzweise verwendet.",
-- 27cc3255 English: Checked tests raid membership only. Unchecked tests party membership or raid
--     membership. A known nonmember is false; unavailable native data stays unavailable, including
--     under NOT.
[3310] = "Aktiviert: prüft nur die Schlachtzugsmitgliedschaft. Deaktiviert: prüft Gruppen- oder Schlachtzugsmitgliedschaft. Ein bekanntes Nichtmitglied ist nicht erfüllt; nicht verfügbare native Daten bleiben nicht verfügbar, auch unter NOT.",
-- d44133b4 English: Choose tabs to browse Rotations, General, Conditions, Functions, Effects, Item
--     Sets, Announces, Profiles and Integrations. The opened panes have their own Help for page
--     controls. Search and filters belong to the current page. Built In entries remain read-only;
--     Duplicate creates an editable copy.
[3311] = "Über die Reiter „Rotationen“, „Allgemein“, „Bedingungen“, „Funktionen“, „Effekte“, „Gegenstandssets“, „Ankündigungen“, „Profile“ und „Integrationen“ navigieren. Die geöffneten Bereiche haben eine eigene Hilfe für ihre Seitensteuerelemente. Suche und Filter gehören zur aktuellen Seite. Integrierte Einträge bleiben schreibgeschützt; „Duplizieren“ erstellt eine bearbeitbare Kopie.",
-- 28510b80 English: Scale changes the whole workbench and its child windows from 70% to 130%. Drag
--     the top-left slider or enter an integer percentage and press Enter. Escape restores the saved
--     scale text. Drag the title bar to move; drag the lower-right corner to resize.
[3312] = "Die Skalierung ändert die gesamte Werkbank und ihre Unterfenster von 70 % bis 130 %. Den Schieberegler oben links ziehen oder einen ganzzahligen Prozentwert eingeben und die Eingabetaste drücken. Escape stellt den gespeicherten Skalierungstext wieder her. Zum Verschieben die Titelleiste ziehen; zum Ändern der Größe die untere rechte Ecke ziehen.",
-- 81701f02 English: Close with X, Escape, or right-click inside the frontmost RM window. Child
--     dialogs have their own close controls and follow the window scale. The language selector
--     changes the workbench language; project links open a copyable address.
[3313] = "Schließen mit X, Escape oder Rechtsklick in das vorderste RM-Fenster. Unterdialoge haben eigene Schließen-Steuerelemente und folgen der Fensterskalierung. Die Sprachauswahl ändert die Sprache der Werkbank; Projektlinks öffnen eine kopierbare Adresse.",
-- ae7a65d1 English: Most settings and source editors keep drafts until Apply. Leaving a dirty page
--     offers Apply, Discard or Cancel; invalid fields remain visible. Profile activation and
--     confirmed replacement, action-bar binding and diagnostic capture have their own explicit
--     actions. Help never applies or discards edits.
[3314] = "Die meisten Einstellungen und Quelltext-Editoren behalten Entwürfe bis „Übernehmen“. Beim Verlassen einer geänderten Seite wird „Übernehmen“, „Verwerfen“ oder „Abbrechen“ angeboten; ungültige Felder bleiben sichtbar. Profilaktivierung und bestätigtes Ersetzen, Aktionsleisten-Bindung und Diagnoseerfassung haben eigene ausdrückliche Aktionen. Die Hilfe übernimmt oder verwirft nie Bearbeitungen.",
-- 2d6b5cc8 English: Gold question marks open full Help for their window, page or card. Hover
--     controls for brief tips. Help does not save settings or commit pending text; spell and item
--     fields keep their native reference tooltips.
[3315] = "Goldene Fragezeichen öffnen die vollständige Hilfe zu ihrem Fenster, ihrer Seite oder Karte. Für kurze Tipps mit der Maus über Steuerelemente fahren. Die Hilfe speichert keine Einstellungen und übernimmt keinen ausstehenden Text; Zauber- und Gegenstandsfelder behalten ihre nativen Referenz-Tooltips.",
-- 8fb57308 English: Open full Help for these controls without applying edits.
[3316] = "Vollständige Hilfe zu diesen Steuerelementen öffnen, ohne Bearbeitungen zu übernehmen.",
-- b9cc9038 English: Explain window navigation, scaling, closing and drafts.
[3317] = "Erklärt Fensternavigation, Skalierung, Schließen und Entwürfe.",
-- 859a4f2c English: Open full Help for this page without switching tabs or applying edits.
[3318] = "Vollständige Hilfe zu dieser Seite öffnen, ohne den Reiter zu wechseln oder Bearbeitungen zu übernehmen.",
-- c0a96039 English: Set the workbench and child-window scale from 70% to 130%; enter a whole
--     percentage or drag the slider.
[3319] = "Skalierung der Werkbank und der Unterfenster festlegen (70 % bis 130 %); einen ganzen Prozentwert eingeben oder den Schieberegler ziehen.",
-- 36760759 English: Edit the value; Enter or leaving the field checks and accepts valid text. Page
--     Help explains when changes are saved.
[3320] = "Wert bearbeiten; die Eingabetaste oder das Verlassen des Feldes prüft gültigen Text und übernimmt ihn. Die Seitenhilfe erklärt, wann Änderungen gespeichert werden.",
-- 43f47d2a English: Click to toggle this option. Page Help explains when changes are saved.
[3321] = "Klicken, um diese Option umzuschalten. Die Seitenhilfe erklärt, wann Änderungen gespeichert werden.",
-- 1b2d4c57 English: Use this control for the current page; page Help explains its options and
--     consequences.
[3322] = "Dieses Steuerelement für die aktuelle Seite verwenden; die Seitenhilfe erklärt seine Optionen und Folgen.",
-- d885c6a2 English: Help for this condition is unavailable. Its registered definition is missing,
--     disabled or waiting for required functions. Opening Help does not register pending or
--     imported source.
[3323] = "Die Hilfe zu dieser Bedingung ist nicht verfügbar. Ihre registrierte Definition fehlt, ist deaktiviert oder wartet auf benötigte Funktionen. Das Öffnen der Hilfe registriert keinen ausstehenden oder importierten Quelltext.",
-- 711bb065 English: This registered condition does not provide Help.
[3324] = "Diese registrierte Bedingung bietet keine Hilfe.",
-- d9c613e5 English: Open Help for this condition without changing its fields.
[3325] = "Hilfe zu dieser Bedingung öffnen, ohne ihre Felder zu ändern.",
-- ac330ed0 English: Select all export text for manual copying. This button does not send it
--     anywhere.
[3326] = "Den gesamten Exporttext zum manuellen Kopieren markieren. Diese Schaltfläche sendet ihn nirgendwohin.",
-- d8332c9a English: Clear the transfer text. A previous preview becomes invalid; saved settings
--     stay unchanged.
[3327] = "Den Übertragungstext leeren. Eine vorherige Vorschau wird ungültig; gespeicherte Einstellungen bleiben unverändert.",
-- 7b980fdf English: Import into the displayed destination. Read the destination and review
--     requirements before continuing.
[3328] = "In das angezeigte Ziel importieren. Vor dem Fortfahren das Ziel lesen und die Anforderungen prüfen.",
-- f71901b9 English: Close this dialog without importing its text.
[3329] = "Diesen Dialog schließen, ohne seinen Text zu importieren.",
-- 536a00ad English: Choose a new named copy or replacement of the selected editable entry.
[3330] = "Eine neue benannte Kopie oder das Ersetzen des ausgewählten bearbeitbaren Eintrags wählen.",
-- 28928c04 English: Set the name for a new copy. Replacement keeps the selected entry as its
--     destination.
[3331] = "Den Namen einer neuen Kopie festlegen. Beim Ersetzen bleibt der ausgewählte Eintrag das Ziel.",
-- 128c10d4 English: Preview import shows everything this import contains, read-only, the way the
--     editor shows it. Nothing is saved.
[3332] = "„Importvorschau“ zeigt alles, was dieser Import enthält, schreibgeschützt, so wie es der Editor darstellt. Es wird nichts gespeichert.",
-- 853ec82f English: Check import lists problems with the text instead of its content: why it cannot
--     be imported and any unsupported data. It does not import or change anything.
[3333] = "„Import prüfen“ listet Probleme mit dem Text auf statt seines Inhalts: warum er sich nicht importieren lässt und welche Daten nicht unterstützt werden. Es wird nichts importiert oder geändert.",
-- 27a3bd58 English: Explain profile import destinations and when changes are saved.
[3334] = "Erklärt die Importziele für Profile und wann Änderungen gespeichert werden.",
-- ca00de4c English: Copy the text to export a profile, or paste profile text to import. The
--     destination controls choose a new profile or replacement of the selected saved profile.
--     Opening Help does not decode, import, or apply the text.
[3335] = "Den Text kopieren, um ein Profil zu exportieren, oder Profiltext zum Importieren einfügen. Die Zielsteuerelemente wählen ein neues Profil oder das Ersetzen des ausgewählten gespeicherten Profils. Das Öffnen der Hilfe dekodiert, importiert oder übernimmt den Text nicht.",
-- 2625de29 English: REPLACE applies immediately to the selected saved profile after Import.
--     Replacing the active profile resets it and applies the imported settings; replacing another
--     profile writes that profile. Reopen the import if the selected saved profile changes.
[3336] = "ERSETZEN wirkt nach dem Import sofort auf das ausgewählte gespeicherte Profil. Das Ersetzen des aktiven Profils setzt es zurück und übernimmt die importierten Einstellungen; das Ersetzen eines anderen Profils überschreibt dieses Profil. Den Import erneut öffnen, wenn sich das ausgewählte gespeicherte Profil ändert.",
-- 74cf2bda English: NEW stages the imported profile in the Profiles editor. Import fills a
--     new-profile draft; the new profile is not saved or activated until you complete the creation
--     controls in that editor. Give it an unused name.
[3337] = "NEU merkt das importierte Profil im Profileditor vor. Der Import füllt einen Entwurf für ein neues Profil; das neue Profil wird erst gespeichert oder aktiviert, wenn die Erstellung in diesem Editor abgeschlossen wird. Einen unbenutzten Namen vergeben.",
-- 00c3d8f9 English: Explain this read-only review of imported source.
[3338] = "Erklärt diese schreibgeschützte Prüfung des importierten Quelltexts.",
-- 3b8fed45 English: This view shows the selected imported function or condition source, its
--     original and destination identifiers, and available metadata. For a condition, choose a
--     callback to inspect its text. This view and its Help do not compile, execute, accept, or
--     register the source. Return to the bundle review to decide whether to import it.
[3339] = "Diese Ansicht zeigt den Quelltext der ausgewählten importierten Funktion oder Bedingung, ihre ursprüngliche und ihre Ziel-Kennung sowie verfügbare Metadaten. Bei einer Bedingung einen Callback wählen, um seinen Text anzusehen. Diese Ansicht und ihre Hilfe kompilieren, führen aus, akzeptieren oder registrieren den Quelltext nicht. Zur Paketprüfung zurückkehren, um über den Import zu entscheiden.",
-- c60faea8 English: Close this read-only source view and return to the bundle review.
[3340] = "Diese schreibgeschützte Quelltextansicht schließen und zur Paketprüfung zurückkehren.",
-- 49411dfb English: Validate the pasted bundle and build a proposed import plan. Review does not
--     apply the plan.
[3341] = "Das eingefügte Paket validieren und einen vorgeschlagenen Importplan erstellen. Die Prüfung wendet den Plan nicht an.",
-- b8726351 English: Include referenced custom function dependencies when producing export text.
[3342] = "Beim Erzeugen des Exporttexts referenzierte benutzerdefinierte Funktionsabhängigkeiten einschließen.",
-- 74de20bd English: Explain dependency-bundle export, review, and explicit import.
[3343] = "Erklärt Export, Prüfung und ausdrücklichen Import von Abhängigkeitspaketen.",
-- 4449aeeb English: Export produces a function or condition bundle, optionally with its custom
--     function dependencies. For import, paste bundle text, choose Review import, inspect the
--     proposed identifiers and conflicts, and review source before applying. Apply import can
--     register trusted Lua source; accept only source you intend to run. Changing the text
--     invalidates the prior plan. Opening Help neither reviews nor applies the bundle.
[3344] = "Der Export erzeugt ein Funktions- oder Bedingungspaket, optional mit seinen benutzerdefinierten Funktionsabhängigkeiten. Zum Import Pakettext einfügen, „Import überprüfen“ wählen, die vorgeschlagenen Kennungen und Konflikte prüfen und den Quelltext vor dem Anwenden ansehen. „Import anwenden“ kann vertrauenswürdigen Lua-Quelltext registrieren; nur Quelltext akzeptieren, der wirklich ausgeführt werden soll. Eine Änderung des Texts macht den vorherigen Plan ungültig. Das Öffnen der Hilfe führt weder eine Prüfung noch einen Import des Pakets durch.",
-- 067adc87 English: Explain rotation preview, destination, and import scope.
[3345] = "Erklärt Rotationsvorschau, Ziel und Importumfang.",
-- fe3fd231 English: Copy the text to export the current rotation, or paste a rotation to import.
--     Choose replacement of the selected editable rotation or a new named copy. Class and This
--     character set the owner of a new copy; replacement keeps the original owner. The imported
--     rotation is opened for editing after a successful import.
[3346] = "Den Text kopieren, um die aktuelle Rotation zu exportieren, oder eine Rotation zum Importieren einfügen. Das Ersetzen der ausgewählten bearbeitbaren Rotation oder eine neue benannte Kopie wählen. „Klasse“ und „Dieser Charakter“ legen den Besitzer einer neuen Kopie fest; beim Ersetzen bleibt der ursprüngliche Besitzer erhalten. Die importierte Rotation wird nach erfolgreichem Import zur Bearbeitung geöffnet.",
-- d6789183 English: With Replace selected entry ticked, the button reads Compare import and shows
--     what would change in that rotation. For a new named copy it reads Preview import and shows
--     everything the import contains, read-only, as the rotation editor shows it. Neither saves
--     anything. Import is enabled only for a ready preview or comparison; changing the text
--     requires another one. Check import shows read-only diagnostics, including unsupported data
--     that prevents import.
[3347] = "Ist „Ausgewählten Eintrag ersetzen“ aktiviert, heißt die Schaltfläche „Import vergleichen“ und zeigt, was sich in dieser Rotation ändern würde. Bei einer neuen benannten Kopie heißt sie „Importvorschau“ und zeigt schreibgeschützt alles, was der Import enthält, so wie es der Rotationseditor darstellt. Keine von beiden speichert etwas. „Importieren“ ist nur bei einer fertigen Vorschau oder einem fertigen Vergleich aktiviert; nach einer Textänderung ist eine neue nötig. „Import prüfen“ zeigt schreibgeschützte Diagnosen, einschließlich nicht unterstützter Daten, die den Import verhindern.",
-- 9a2297f1 English: Explain this read-only incoming rotation comparison.
[3348] = "Erklärt diesen schreibgeschützten Vergleich der eingehenden Rotation.",
-- 4f0c847b English: This view compares the saved or exported rotation with the current incoming
--     preview. It does not apply changes. Close it to choose the destination and import from the
--     transfer dialog. A changed preview, closed owner, or changed profile retires this comparison
--     Help.
[3349] = "Diese Ansicht vergleicht die gespeicherte oder exportierte Rotation mit der aktuellen eingehenden Vorschau. Sie übernimmt keine Änderungen. Die Ansicht schließen, um im Übertragungsdialog das Ziel zu wählen und zu importieren. Eine geänderte Vorschau, ein geschlossener Besitzer oder ein geändertes Profil macht diese Vergleichshilfe hinfällig.",
-- c091ac0b English: Compare import shows what would change in the entry you are replacing, side by
--     side with its current content. Nothing is saved.
[3350] = "„Import vergleichen“ zeigt, was sich im zu ersetzenden Eintrag ändern würde, neben seinem aktuellen Inhalt. Es wird nichts gespeichert.",
-- 64144a9e English: Explain this read-only preview of the incoming rotation.
[3351] = "Erklärt diese schreibgeschützte Vorschau der eingehenden Rotation.",
-- 91ca45b8 English: This view shows the rotation as it would be imported: name, specializations,
--     switch condition, steps and cooldowns. It is read-only and works on a copy; it saves and
--     changes nothing. Close it to choose the destination and import from the transfer dialog. A
--     changed text, closed transfer or changed profile retires this Help.
[3352] = "Diese Ansicht zeigt die Rotation, wie sie importiert würde: Name, Spezialisierungen, Umschaltbedingung, Schritte und Abklingzeiten. Sie ist schreibgeschützt, arbeitet mit einer Kopie und speichert oder ändert nichts. Schließen, um im Übertragungsdialog das Ziel zu wählen und zu importieren. Ein geänderter Text, eine geschlossene Übertragung oder ein geändertes Profil macht diese Hilfe hinfällig.",
-- 5ac254c6 English: Macro invocation
-- Context: Help topic title in the Announces help: an example of how a macro calls an announcement.
[3353] = "Makroaufruf",
-- 94a47c93 English: Supplied macro unit
-- Context: Help topic title in the Announces help: the unit that a macro passes to the
--     announcement.
[3354] = "Übergebene Makroeinheit",
-- c3039a0d English: Invoke this saved identifier directly from your macro. The supplied unit
--     controls Announcement target conditions and Whisper; there is no implicit target.
[3355] = "Diese gespeicherte Kennung direkt aus Ihrem Makro aufrufen. Die übergebene Einheit steuert Bedingungen mit „Ankündigungsziel“ sowie „Flüstern“; es gibt kein implizites Ziel.",
-- d4f140f6 English: Via Script/Macro is invoked by its saved Identifier rather than a cast event.
--     It does not require a stored spell or item. Current conditions must match before any output.
--     This call attempts output synchronously; it does not establish that a spell was cast or
--     succeeded.
[3356] = "„Per Skript/Makro“ wird über seine gespeicherte Kennung aufgerufen statt über ein Zauberereignis. Ein gespeicherter Zauber oder Gegenstand ist nicht erforderlich. Die aktuellen Bedingungen müssen vor jeder Ausgabe erfüllt sein. Dieser Aufruf versucht die Ausgabe synchron; er belegt nicht, dass ein Zauber gewirkt wurde oder erfolgreich war.",
-- 978b4fbf English: Use a unique, case-sensitive identifier of at most 64 ASCII characters. Start
--     with a letter or underscore; subsequent characters may also include digits, dots or hyphens.
--     Identifiers are scoped to the active profile, including disabled entries. Duplicate assigns a
--     distinct identifier; ambiguous imports and Apply are rejected.
[3357] = "Eine eindeutige Kennung aus höchstens 64 ASCII-Zeichen verwenden; Groß-/Kleinschreibung wird unterschieden. Sie muss mit einem Buchstaben oder Unterstrich beginnen; die folgenden Zeichen dürfen auch Ziffern, Punkte oder Bindestriche sein. Kennungen gelten innerhalb des aktiven Profils, deaktivierte Einträge eingeschlossen. Duplizieren vergibt eine eigene Kennung; mehrdeutige Importe und Übernehmen werden abgelehnt.",
-- 7247934f English: Use /run RM_Annouce('FOO','mouseover',nil). RM_Announce is the same function.
--     The target unit and spell are optional: /run RM_Announce('FOO',nil,403) or /run
--     RM_Announce('FOO','target','Lightning Bolt'). Spell names depend on client language.
--     {{event}} becomes Via Script/Macro; {{target}} and {{spell}} use the supplied arguments. A
--     required missing argument skips output. {{item}} is not supplied by this API. A resurrection
--     message announces an attempt, not a completed resurrection. Examples are text only; RM does
--     not create or execute macros.
[3358] = "/run RM_Annouce('FOO','mouseover',nil) verwenden. RM_Announce ist dieselbe Funktion. Zieleinheit und Zauber sind optional: /run RM_Announce('FOO',nil,403) oder /run RM_Announce('FOO','target','Blitzschlag'). Zaubernamen hängen von der Clientsprache ab. {{event}} wird zu „Per Skript/Makro“; {{target}} und {{spell}} verwenden die übergebenen Argumente. Fehlt ein benötigtes Argument, entfällt die Ausgabe. {{item}} wird von dieser API nicht geliefert. Eine Wiederbelebungsnachricht kündigt einen Versuch an, keine abgeschlossene Wiederbelebung. Die Beispiele sind nur Text; RM erstellt keine Makros und führt keine aus.",
-- fda702d4 English: Supply a readable unit token such as mouseover, target or focus. RM resolves
--     that exact unit name and rechecks its identity during delivery. Announcement target
--     conditions and Whisper use this same unit. Omitting the argument does not use your selected
--     target, yourself, a prior cast or a prior macro call. Missing Announcement target data
--     remains unavailable, including under NOT.
[3359] = "Eine lesbare Einheitenkennung wie mouseover, target oder focus angeben. RM löst genau diesen Einheitennamen auf und prüft dessen Identität bei der Zustellung erneut. Bedingungen zum Ankündigungsziel und Flüstern verwenden dieselbe Einheit. Ohne das Argument werden weder Ihr ausgewähltes Ziel noch Sie selbst, ein früherer Zauber oder ein früherer Makroaufruf verwendet. Fehlende Daten zum Ankündigungsziel bleiben nicht verfügbar, auch unter NOT.",
-- 4c48bcf5 English: Checked directs a named emote to the supplied macro unit. Missing or unreadable
--     target data skips the targeted emote; unchecked is targetless.
[3360] = "Aktiviert richtet ein benanntes Emote an die übergebene Makroeinheit. Bei fehlenden oder unlesbaren Zieldaten entfällt das gezielte Emote; deaktiviert erfolgt es ohne Ziel.",
-- 4dbc9c41 English: Available only for Via Script/Macro. Attempt a Say message directly in the
--     invoking call. Blizzard may reject macro-origin chat, including during instance encounters;
--     RM does not attest hardware input, defer delivery, retry or guarantee visible output.
[3361] = "Nur für „Per Skript/Makro“ verfügbar. Versucht, eine Sagen-Nachricht direkt im auslösenden Aufruf zu senden. Blizzard kann Chat aus Makros ablehnen, auch während Instanzbegegnungen; RM bestätigt keine Hardware-Eingabe, verzögert die Zustellung nicht, wiederholt nichts und garantiert keine sichtbare Ausgabe.",
-- a1cf5fb0 English: Available only for Via Script/Macro. Attempt a Yell message directly in the
--     invoking call. Native macro and encounter restrictions still apply; a completed API call is
--     not confirmation of delivery.
[3362] = "Nur für „Per Skript/Makro“ verfügbar. Versucht, eine Schreien-Nachricht direkt im auslösenden Aufruf zu senden. Native Makro- und Begegnungsbeschränkungen gelten weiterhin; ein abgeschlossener API-Aufruf ist keine Zustellbestätigung.",
-- a736bec3 English: Available only for Via Script/Macro. Whisper uses the exact supplied unit name
--     and requires a readable player identity. No target means no Whisper. Native macro and
--     encounter restrictions still apply; RM never substitutes another recipient or retries.
[3363] = "Nur für „Per Skript/Makro“ verfügbar. Flüstern verwendet genau den übergebenen Einheitennamen und benötigt eine lesbare Spieleridentität. Ohne Ziel kein Flüstern. Native Makro- und Begegnungsbeschränkungen gelten weiterhin; RM setzt nie einen anderen Empfänger ein und wiederholt nichts.",
-- b6082c37 English: Offer this condition type when editing announcement conditions. This flag is
--     independent of Switch Condition and does not remove or invalidate conditions already saved in
--     announcements.
[3364] = "Diesen Bedingungstyp beim Bearbeiten von Ankündigungsbedingungen anbieten. Diese Option ist unabhängig von „Umschaltbedingung“ und entfernt oder entwertet keine bereits in Ankündigungen gespeicherten Bedingungen.",
-- 45320409 English: One trigger can send an ordered series of outputs. Each expanded card has its
--     own destination, text or sound, conditions and enabled state. Help describes that card.
--     Duplicate makes an independent card; delete removes it. Use the arrows, or drag a card from
--     anywhere on it, to change order. Add output, on the Outputs header row, appends a card; drag
--     it into a gap to insert one there. A legacy announcement stays unchanged on display. Adding,
--     duplicating or removing a card, choosing Channel, or changing to an action type that cannot
--     use its saved destination converts only the draft to output cards. Up to 64 outputs are
--     allowed; an empty series sends nothing. Apply saves the draft and Discard restores it.
[3365] = "Ein Auslöser kann eine geordnete Reihe von Ausgaben senden. Jede aufgeklappte Karte hat ihr eigenes Ausgabeziel, ihren Text oder Ton, ihre Bedingungen und ihren Aktivierungsstatus. Hilfe beschreibt diese Karte. Duplizieren erstellt eine unabhängige Karte; Löschen entfernt sie. Die Reihenfolge mit den Pfeilen ändern oder eine Karte an beliebiger Stelle greifen und ziehen. „Ausgabe hinzufügen“ in der Kopfzeile „Ausgaben“ hängt eine Karte an; in eine Lücke gezogen, wird sie dort eingefügt. Eine ältere Ankündigung bleibt in der Anzeige unverändert. Hinzufügen, Duplizieren oder Entfernen einer Karte, die Wahl von „Kanal“ oder der Wechsel zu einem Aktionstyp, der das gespeicherte Ausgabeziel nicht verwenden kann, wandelt nur den Entwurf in Ausgabekarten um. Bis zu 64 Ausgaben sind erlaubt; eine leere Reihe sendet nichts. Übernehmen speichert den Entwurf, Verwerfen stellt den gespeicherten Stand wieder her.",
-- 3c9708b1 English: Via Script/Macro outputs can send to a joined chat channel. Open Channel to
--     refresh the joined names, then select the exact name. A saved name remains visible when
--     unavailable; that output is skipped until the channel is joined under that name. Numeric
--     channel IDs are not saved and channels are never joined automatically. Native delivery
--     permissions still apply.
[3366] = "Ausgaben vom Typ „Per Skript/Makro“ können an einen beigetretenen Chatkanal senden. „Kanal“ öffnen, um die Namen der beigetretenen Kanäle zu aktualisieren, dann genau den Namen auswählen. Ein gespeicherter Name bleibt sichtbar, auch wenn er nicht verfügbar ist; diese Ausgabe wird übersprungen, bis dem Kanal unter diesem Namen beigetreten wurde. Numerische Kanal-IDs werden nicht gespeichert, und Kanälen wird nie automatisch beigetreten. Native Zustellberechtigungen gelten weiterhin.",
-- 6de77638 English: Choose an announcement trigger, then edit its always expanded output cards.
--     Each card has a destination, conditions, enabled state and Help. Add, duplicate, delete, move
--     or drag outputs within the announcement. Joined channel names are available for Via
--     Script/Macro. New opens a draft; Apply saves it and Discard restores it. Imports are
--     validated and never execute code.
[3367] = "Einen Ankündigungsauslöser wählen und dann dessen stets aufgeklappte Ausgabekarten bearbeiten. Jede Karte hat ein Ausgabeziel, Bedingungen, einen Aktivierungsstatus und Hilfe. Ausgaben innerhalb der Ankündigung hinzufügen, duplizieren, löschen, verschieben oder ziehen. Namen beigetretener Kanäle sind für „Per Skript/Makro“ verfügbar. Neu öffnet einen Entwurf; Übernehmen speichert ihn, Verwerfen stellt den gespeicherten Stand wieder her. Importe werden validiert und führen nie Code aus.",
-- 318a2558 English: Recommends whatever spell Blizzard's Assisted Combat suggests next, read each
--     time the rotation is evaluated. It highlights that spell's button and shows in the preview
--     like a spell step, and is held to the same requirements: known, usable, off cooldown and in
--     range. When nothing is suggested, the suggested spell is not on your bars, or Assisted Combat
--     is unavailable (anywhere but Retail, or a specialization without it), the step is skipped.
--     Rotation list only.
[3368] = "Empfiehlt den Zauber, den Blizzards Kampfassistent als Nächstes vorschlägt, neu gelesen bei jeder Auswertung der Rotation. Er hebt die Taste dieses Zaubers hervor, erscheint in der Vorschau wie ein Zauberschritt und unterliegt denselben Anforderungen: bekannt, einsetzbar, nicht in Abklingzeit und in Reichweite. Wenn nichts vorgeschlagen wird, der vorgeschlagene Zauber nicht auf Ihren Leisten liegt oder der Kampfassistent nicht verfügbar ist (überall außer in Retail oder bei einer Spezialisierung ohne ihn), wird der Schritt übersprungen. Nur in der Rotationsliste.",
-- d462cf8d English: Who highlights the button while a "Blizzard's suggestion" step is the
--     recommendation. Rotation Master's glow uses the effect below. Blizzard's Assisted Highlight
--     turns on the game's own highlight (Options, Gameplay, Combat, Assisted Highlight) while a
--     rotation with that step is active, and Rotation Master leaves that step's button to it; Both
--     shows the two. Rotation Master turns Blizzard's highlight on only outside combat, never
--     changes it if it was already on, and puts your setting back when the rotation ends, Rotation
--     Master is disabled, or you log out or reload. If you change the setting yourself meanwhile,
--     your choice is kept. Blizzard's highlight follows Blizzard's suggestion all the time, also
--     while another step is recommended, and it shows on Blizzard's own action bars only, so choose
--     Rotation Master's glow or Both with a bar addon. The choice is hidden on clients without
--     Blizzard's highlight (Forever and the Classic clients).
[3369] = "Wer die Taste hervorhebt, während ein Schritt „Blizzards Vorschlag“ die Empfehlung ist. Der Leuchteffekt von Rotation Master verwendet den Effekt unten. Blizzards Unterstützte Hervorhebung schaltet die eigene Hervorhebung des Spiels ein (Optionen, Gameplay, Kampf, Unterstützte Hervorhebung), solange eine Rotation mit diesem Schritt aktiv ist, und Rotation Master überlässt ihr die Taste dieses Schritts; Beides zeigt beide. Rotation Master schaltet Blizzards Hervorhebung nur außerhalb des Kampfes ein, ändert sie nie, wenn sie schon eingeschaltet war, und stellt Ihre Einstellung wieder her, wenn die Rotation endet, Rotation Master deaktiviert wird oder Sie sich abmelden oder neu laden. Ändern Sie die Einstellung währenddessen selbst, bleibt Ihre Wahl erhalten. Blizzards Hervorhebung folgt Blizzards Vorschlag die ganze Zeit, auch wenn ein anderer Schritt empfohlen wird, und erscheint nur auf Blizzards eigenen Aktionsleisten; wählen Sie daher mit einem Leistenaddon den Leuchteffekt von Rotation Master oder Beides. Die Auswahl ist auf Clients ohne Blizzards Hervorhebung ausgeblendet (Forever und die Classic-Clients).",
-- e031d376 English: Add Rotation Master lines to spell and item tooltips. This is the master
--     switch: off, Rotation Master adds nothing to any tooltip, and the options below do nothing.
--     Lines are only added, never read from the tooltip, so other tooltip addons are unaffected.
[3370] = "Fügt Zauber- und Gegenstands-Tooltips Zeilen von Rotation Master hinzu. Das ist der Hauptschalter: Ist er aus, fügt Rotation Master keinem Tooltip etwas hinzu, und die Optionen darunter haben keine Wirkung. Zeilen werden nur hinzugefügt und nie aus dem Tooltip gelesen, daher bleiben andere Tooltip-Addons unberührt.",
-- b52dc56f English: In an item tooltip, list the Rotation Master item sets that contain the item:
--     your profile's and the shared ones from the Item Sets page. Names beyond the limit below end
--     the line with how many more there are.
[3371] = "Listet im Tooltip eines Gegenstands die Rotation-Master-Gegenstandssets auf, die ihn enthalten: die Sets deines Profils und die gemeinsamen von der Seite Gegenstandssets. Namen über dem Limit unten werden am Zeilenende als Anzahl weiterer Namen angegeben.",
-- a142e568 English: In a spell or item tooltip, list the rotations for your current specialization
--     that use it as a step in the rotation or cooldown list. A rotation that is switched off is
--     shown dimmed and marked disabled. Built In rotations that are not for this version of the
--     game or your specialization are left out. The list is refreshed out of combat after a
--     rotation or item set changes.
[3372] = "Listet im Tooltip eines Zaubers oder Gegenstands die Rotationen für deine aktuelle Spezialisierung auf, die ihn als Schritt in der Rotations- oder Abklingzeitenliste verwenden. Eine ausgeschaltete Rotation wird abgedunkelt und als deaktiviert markiert. Integrierte Rotationen, die nicht für diese Spielversion oder deine Spezialisierung gelten, werden weggelassen. Die Liste wird außerhalb des Kampfes aktualisiert, nachdem sich eine Rotation oder ein Gegenstandsset geändert hat.",
-- 5e8b512d English: Also count a spell or item that appears only inside a condition (for example
--     "spell is ready" or "item is carried"), not just as a step. Off by default because it lists
--     more rotations.
[3373] = "Zählt auch einen Zauber oder Gegenstand, der nur innerhalb einer Bedingung vorkommt (zum Beispiel \"Zauber ist bereit\" oder \"Gegenstand wird mitgeführt\"), nicht nur als Schritt. Standardmäßig aus, weil dann mehr Rotationen aufgelistet werden.",
-- dffd6006 English: How many names a tooltip line lists before it ends with "(+N more)". A lower
--     number keeps tooltips short.
[3374] = "Wie viele Namen eine Tooltip-Zeile auflistet, bevor sie mit \"(+N weitere)\" endet. Ein niedrigerer Wert hält Tooltips kurz.",
-- 83e079d3 English: Your talent specialization. Choose a class, then one of its specializations;
--     your own class is selected first, and other classes are offered for rotations shared between
--     characters. A specialization of another class is always false.
[3375] = "Ihre Talentspezialisierung. Wählen Sie eine Klasse und dann eine ihrer Spezialisierungen; Ihre eigene Klasse ist zuerst ausgewählt, und andere Klassen werden für Rotationen angeboten, die zwischen Charakteren geteilt werden. Eine Spezialisierung einer anderen Klasse ist immer nicht erfüllt.",
-- a449bf6b English: Retail and Mists of Pandaria Classic compare your active specialization.
--     Classic Era, Burning Crusade and Wrath compare your primary talent tree, the one tree with
--     the most points; Feral and Guardian both mean Feral Combat there. Forever cannot tell its
--     specializations apart this way. No specialization yet, tied or unspent trees and unreadable
--     values are unavailable, including under NOT. The answer is cached until your talents or
--     specialization change.
[3376] = "Retail und Mists of Pandaria Classic vergleichen Ihre aktive Spezialisierung. Classic Era, Burning Crusade und Wrath vergleichen Ihren primären Talentbaum, den einen Baum mit den meisten Punkten; Wilder Kampf und Wächter bedeuten dort beide Wilder Kampf. Forever kann seine Spezialisierungen auf diese Weise nicht unterscheiden. Noch keine Spezialisierung, gleichstehende oder nicht verteilte Bäume und nicht lesbare Werte sind nicht verfügbar, auch unter NOT. Die Antwort wird zwischengespeichert, bis sich Ihre Talente oder Ihre Spezialisierung ändern.",
-- 86569ac1 English: What is equipped in the main hand, off hand or ranged slot: nothing, any
--     weapon, a one-handed, two-handed or ranged weapon, a shield, an off-hand item, or one weapon
--     type such as Daggers. Types are read from the item's class and subclass, so they work in
--     every language. The answer is cached until your equipment changes.
[3377] = "Was im Waffenhand-, Schildhand- oder Fernkampfplatz angelegt ist: nichts, eine beliebige Waffe, eine Einhand-, Zweihand- oder Fernkampfwaffe, ein Schild, ein Gegenstand für die Schildhand oder ein bestimmter Waffentyp wie Dolche. Die Typen werden aus Klasse und Unterklasse des Gegenstands gelesen und funktionieren daher in jeder Sprache. Die Antwort wird zwischengespeichert, bis sich Ihre Ausrüstung ändert.",
-- 96a5754f English: Dual wielding: off hand holds any weapon. Titan's Grip: off hand holds a
--     two-handed weapon. Backstab and Ambush: main hand holds Daggers. Shield Slam or a tank set:
--     off hand holds a shield. The ranged slot exists only before Mists of Pandaria; elsewhere, and
--     while item data is still loading, this condition is unavailable, including under NOT.
[3378] = "Beidhändiges Kämpfen: Die Schildhand hält eine beliebige Waffe. Titanengriff: Die Schildhand hält eine Zweihandwaffe. Meucheln und Hinterhalt: Die Waffenhand hält Dolche. Schildschlag oder ein Tank-Set: Die Schildhand hält einen Schild. Der Fernkampfplatz existiert nur vor Mists of Pandaria; anderswo und solange die Gegenstandsdaten noch laden, ist diese Bedingung nicht verfügbar, auch unter NOT.",
-- 0e0d00b2 English: Not on your action bars
[3379] = "Nicht auf Ihren Aktionsleisten",
-- c8117094 English: An amber border and warning mark a card whose action no action bar button holds
--     right now. Rotation Master highlights an action by lighting the button that holds it, so that
--     step is skipped (a cooldown is never shown) until you put it on a bar. The warning updates
--     when your bars change. Red still marks invalid data.
[3380] = "Ein bernsteinfarbener Rand und ein Warnzeichen kennzeichnen eine Karte, deren Aktion gerade keine Aktionsleistentaste hält. Rotation Master hebt eine Aktion hervor, indem es die Taste leuchten lässt, die sie hält, daher wird dieser Schritt übersprungen (eine Abklingzeit wird nie angezeigt), bis Sie sie auf eine Leiste legen. Die Warnung aktualisiert sich, wenn sich Ihre Leisten ändern. Rot kennzeichnet weiterhin ungültige Daten.",
-- 2c7e6247 English: Actions must also be on an action bar: Rotation Master highlights an action by
--     lighting the button that holds it, so a step or cooldown that no button holds is skipped, and
--     its card shows an amber warning.
[3381] = "Aktionen müssen außerdem auf einer Aktionsleiste liegen: Rotation Master hebt eine Aktion hervor, indem es die Taste leuchten lässt, die sie hält, daher wird ein Schritt oder eine Abklingzeit, die keine Taste hält, übersprungen, und seine Karte zeigt eine bernsteinfarbene Warnung.",
-- cc011249 English: Matches while the game says a boss encounter is in progress. Unlike the Boss
--     Mod Encounter condition it needs no boss mod, and it knows nothing of which boss or stage it
--     is. It starts when the encounter starts and ends on a kill, a wipe or a reset. It reads in
--     combat on every edition, Retail and Forever included.
[3382] = "Trifft zu, solange das Spiel meldet, dass eine Bossbegegnung läuft. Anders als die Bedingung Boss-Mod-Begegnung braucht sie kein Boss-Mod und weiß nicht, welcher Boss oder welche Phase es ist. Sie beginnt mit dem Start der Begegnung und endet bei Sieg, Wipe oder Zurücksetzen. Sie lässt sich in jeder Edition im Kampf lesen, auch in Retail und Forever.",
-- bec26f34 English: The level of the Mythic+ keystone you are running. It is 0 whenever you are not
--     in a Mythic+ dungeon, so 'at least 10' is only true inside a run of that level. Retail only.
[3383] = "Die Stufe des Mythic+-Schlüsselsteins, den Sie gerade spielen. Sie ist 0, solange Sie in keinem Mythic+-Dungeon sind; „mindestens 10“ trifft also nur in einem Durchlauf dieser Stufe zu. Nur Retail.",
-- a4530fa7 English: The hero talent tree you have chosen. Pick a tree from the list, which shows
--     the trees of the rotation's specialization, or choose 'Any hero talent tree' to match once
--     you have chosen one. A tree can also be entered by its ID, to share a rotation with another
--     class. Below the level that offers hero talents, or before you pick a tree, no tree is
--     chosen. Retail only.
[3384] = "Der Heldentalentbaum, den Sie gewählt haben. Wählen Sie einen Baum aus der Liste, die die Bäume der Spezialisierung der Rotation zeigt, oder „Beliebiger Heldentalentbaum“, um zu prüfen, ob Sie überhaupt einen gewählt haben. Ein Baum lässt sich auch über seine ID eingeben, um eine Rotation mit einer anderen Klasse zu teilen. Unterhalb der Stufe, ab der es Heldentalente gibt, oder bevor Sie einen Baum wählen, ist kein Baum gewählt. Nur Retail.",
-- 88cf82f7 English: Matches while the game shows the activation glow on this spell, the golden
--     border an action button gets when a proc makes the spell castable or stronger. It asks the
--     game directly, so it still reads when the buff behind the proc is hidden from addons in
--     combat. Choose the spell as it appears on your bars; its base and override forms are checked
--     too. Unavailable, never simply false, if the game cannot answer.
[3385] = "Trifft zu, solange das Spiel auf diesem Zauber das Aktivierungsleuchten zeigt, den goldenen Rand, den eine Aktionsleiste-Taste bekommt, wenn ein Proc den Zauber wirkbar oder stärker macht. Es fragt das Spiel direkt, liest also auch dann, wenn der Segen hinter dem Proc im Kampf vor Addons verborgen ist. Wählen Sie den Zauber so, wie er auf Ihren Leisten steht; seine Basis- und Ersatzformen werden ebenfalls geprüft. Nicht verfügbar, niemals einfach falsch, wenn das Spiel nicht antworten kann.",
-- c9e6ec28 English: How happy your Hunter pet is: Unhappy, Content or Happy, as the game reports
--     it. No pet, or a pet that is not a Hunter pet, is in none of these moods. Classic Era,
--     Burning Crusade and Wrath only.
[3386] = "Wie zufrieden Ihr Jägerbegleiter ist: Unzufrieden, Zufrieden oder Glücklich, so wie das Spiel es meldet. Kein Begleiter oder ein Begleiter, der kein Jägerbegleiter ist, befindet sich in keiner dieser Stimmungen. Nur Classic Era, Burning Crusade und Wrath.",
-- d6742b74 English: The damage waiting in your Brewmaster Monk's Stagger pool, or, with the box
--     ticked, that damage as a percent of your maximum health. Mists of Pandaria, Retail and
--     Forever only. On Retail and Forever the game can hide the pool from addons in combat, and
--     always hides maximum health, so the percent form is unavailable there and the amount is
--     unavailable whenever the game hides it; neither is ever guessed.
[3387] = "Der Schaden, der in der Staffelung Ihres Braumeister-Mönchs wartet, oder bei gesetztem Häkchen dieser Schaden als Prozent Ihrer maximalen Gesundheit. Nur Mists of Pandaria, Retail und Forever. In Retail und Forever kann das Spiel den Vorrat im Kampf vor Addons verbergen und verbirgt die maximale Gesundheit immer, daher ist die Prozentform dort nicht verfügbar und der Betrag nicht verfügbar, sobald das Spiel ihn verbirgt; nichts davon wird je geschätzt.",
-- 22cccaf0 English: Advise a spell even when you do not have the mana or other resource for it
--     right now. Without this, a spell you cannot afford is skipped like any other step that is not
--     ready. The spell must still be learned, off cooldown and usable for another reason, and its
--     conditions still apply.
[3388] = "Empfiehlt einen Zauber auch dann, wenn Ihnen gerade Mana oder eine andere Ressource dafür fehlt. Ohne diese Option wird ein Zauber, den Sie sich nicht leisten können, wie jeder andere nicht bereite Schritt übersprungen. Der Zauber muss weiterhin erlernt sein, darf nicht auf Abklingzeit sein und muss aus anderen Gründen verwendbar sein; seine Bedingungen gelten weiterhin.",
-- 1bf91ced English: Retail and Forever can hide whether a spell is usable from addons in some
--     situations. The spell is then skipped whether or not this option is on.
[3389] = "Retail und Forever können vor Addons in manchen Situationen verbergen, ob ein Zauber verwendbar ist. Der Zauber wird dann übersprungen, unabhängig davon, ob diese Option aktiv ist.",
-- 0c4bd263 English: Advise a spell or item even when your target is out of its range. Without this,
--     a step whose range check fails is skipped. The spell or item must still be learned or owned,
--     off cooldown and usable, and its conditions still apply.
[3390] = "Empfiehlt einen Zauber oder Gegenstand auch dann, wenn sich Ihr Ziel außerhalb seiner Reichweite befindet. Ohne diese Option wird ein Schritt, dessen Reichweitenprüfung fehlschlägt, übersprungen. Zauber oder Gegenstand müssen weiterhin erlernt bzw. vorhanden sein, dürfen nicht auf Abklingzeit sein und müssen verwendbar sein; ihre Bedingungen gelten weiterhin.",
-- cb691e6c English: Adopt several at once
[3391] = "Mehrere auf einmal zuordnen",
-- 6ac62581 English: Adopt all and Adopt all from specialization adopt every listed record in one
--     step, for the owner chosen under Applies to. Each record is adopted on its own, exactly as a
--     single adoption would be: a record whose destination already exists, or that is incomplete,
--     stays in the archive and is named in the result.
[3392] = "„Alle zuordnen“ und „Alle der Spezialisierung zuordnen“ ordnen jeden aufgelisteten Eintrag in einem Schritt dem unter „Gilt für“ gewählten Eigentümer zu. Jeder Eintrag wird einzeln zugeordnet, genau wie bei einer einzelnen Zuordnung: Ein Eintrag, dessen Ziel bereits existiert oder der unvollständig ist, bleibt im Archiv und wird im Ergebnis genannt.",
-- d6efe8ce English: Recommends placing a raid target marker on a unit (you, your target, focus,
--     mouseover, pet or their targets), or clearing the marker with the Clear the mark choice.
--     Rotation Master never places the mark itself: it lights an action bar button, and you press
--     it. Choose Put on an action bar to make a macro for the step and drop it on a slot, or write
--     /click RM_Mark_target_skull in a macro of your own (the button is RM_Mark_ then the unit, an
--     underscore and the mark in lower case, or none to clear; it is made the first time the step
--     is evaluated out of combat). The step is skipped while no action bar holds its macro, the
--     unit does not exist, the unit already carries that mark, or you may not place marks: in a
--     party anyone can, in a raid only the leader and assistants. Rotation list only.
[4087] = "Empfiehlt, eine Schlachtzugsmarkierung auf eine Einheit zu setzen (auf Sie, Ihr Ziel, Fokus, Mouseover, Begleiter oder deren Ziele) oder sie mit der Auswahl Markierung entfernen zu löschen. Rotation Master setzt die Markierung nie selbst: Es hebt einen Button der Aktionsleiste hervor, und Sie drücken ihn. Wählen Sie In eine Aktionsleiste legen, um ein Makro für den Schritt zu erstellen und auf einen Platz zu legen, oder schreiben Sie /click RM_Mark_target_skull in ein eigenes Makro (der Button heißt RM_Mark_, dann die Einheit, ein Unterstrich und die Markierung in Kleinbuchstaben, oder none zum Entfernen; er wird beim ersten Auswerten des Schritts außerhalb des Kampfes erstellt). Der Schritt wird übersprungen, solange keine Aktionsleiste sein Makro enthält, die Einheit nicht existiert, die Einheit die Markierung schon trägt oder Sie keine Markierungen setzen dürfen: In einer Gruppe darf es jeder, in einem Schlachtzug nur der Leiter und die Assistenten. Nur in der Rotationsliste.",
-- e3334d5c English: Also list the rotations for your current specialization that are switched off,
--     dimmed and marked disabled, after the ones that are on. Turn this off to list only rotations
--     that are on; the "(+N more)" count then leaves the switched-off ones out too.
[4090] = "Listet zusätzlich die Rotationen deiner aktuellen Spezialisierung auf, die ausgeschaltet sind, abgedunkelt und als deaktiviert markiert, nach den eingeschalteten. Schalte dies aus, um nur eingeschaltete Rotationen aufzulisten; die Angabe \"(+N weitere)\" lässt die ausgeschalteten dann ebenfalls aus.",
-- 766abde1 English: With rotation conditions included, leave out any condition that is switched off
--     in the rotation editor, together with everything under it, because a disabled condition no
--     longer affects the rotation. Off by default: a spell or item that appears only in a disabled
--     condition still counts.
[4091] = "Wenn Rotationsbedingungen einbezogen werden, lässt dies jede Bedingung weg, die im Rotationseditor ausgeschaltet ist, samt allem darunter, weil eine deaktivierte Bedingung die Rotation nicht mehr beeinflusst. Standardmäßig aus: Ein Zauber oder Gegenstand, der nur in einer deaktivierten Bedingung vorkommt, wird weiterhin gezählt.",
}
